/* 术语注释词典：讲义正文自动加放大镜，点开显示释义 */
window.STUDY = window.STUDY || { chapters: [], cheats: [] };

window.STUDY.terms = [
  /* ---------- 第 1 章 ---------- */
  { term: '人工智能', full: 'Artificial Intelligence', alias: ['AI'], ch: 1, def: '让机器具备感知、学习、推理、生成、决策能力的技术。判断一项技术是否属于人工智能，可以看它是否提供这五种能力中的一种。' },
  { term: '弱人工智能', full: 'Artificial Narrow Intelligence', alias: ['ANI'], ch: 1, def: '只擅长单一任务的人工智能，例如人脸识别、下棋、语音助手。当前所有实际应用都属于这一级。' },
  { term: '通用人工智能', full: 'Artificial General Intelligence', alias: ['AGI'], ch: 1, def: '能够在多种任务与领域之间迁移、达到人类水平的人工智能，目前尚未实现。' },
  { term: '超人工智能', full: 'Artificial Superintelligence', alias: ['ASI'], ch: 1, def: '在几乎所有领域全面超越人类的假想人工智能，仍停留在理论讨论阶段。' },
  { term: '符号主义', full: 'Symbolism', ch: 1, def: '认为智能来自符号表示与逻辑推理的学派。它把知识写成规则，由推理机按规则推导结论，专家系统是代表成果。' },
  { term: '联结主义', full: 'Connectionism', ch: 1, def: '认为智能来自大量简单单元的连接与权重学习的学派。神经网络通过数据不断调整连接强度，从样本中学出规律。' },
  { term: '行为主义', full: 'Behaviorism', ch: 1, def: '认为智能来自感知与动作的反馈闭环的学派。系统在环境中尝试动作，根据奖励与惩罚调整行为，强化学习是代表方向。' },
  { term: '进化主义', full: 'Evolutionism', ch: 1, def: '用遗传算法、进化策略等生物进化思路求解问题的计算智能分支，不属于人工智能三大核心学派。' },
  { term: '计算智能', full: 'Computational Intelligence', ch: 1, def: '以模糊逻辑、神经网络、进化计算等为主要方法的智能研究分支，强调数值计算与自适应能力。' },
  { term: '图灵测试', full: 'Turing Test', ch: 1, def: '1950 年图灵提出的智能判据：测试者通过纯文本对话分辨不出对面是人还是机器，就认为机器具有智能。它把「机器能思考吗」转化为可操作的实验。' },
  { term: '模仿游戏', full: 'Imitation Game', ch: 1, def: '图灵测试最初的名字。测试者分别与人和机器进行文字交流，任务是根据回答判断谁是机器。' },
  { term: '中文房间', full: 'Chinese Room', ch: 1, def: '哲学家塞尔提出的思想实验：房间里的人按规则手册处理中文符号，外部看来说话流利，但他并不懂中文。用来反驳「通过图灵测试就等于理解」。' },
  { term: '操作主义', full: 'Operationalism', ch: 1, def: '用可观察、可测量的操作来定义概念的做法。图灵测试用对话行为定义智能，避开了「思考」本身的哲学争议。' },
  { term: '达特茅斯会议', full: 'Dartmouth Workshop', ch: 1, def: '1956 年夏天在达特茅斯学院举行的研讨会，麦卡锡、明斯基、香农、罗切斯特等人参加，正式使用 Artificial Intelligence 这一名称，被视为人工智能学科诞生的标志。' },
  { term: '专家系统', full: 'Expert System', ch: 1, def: '把领域专家的知识写成规则库，再由推理机根据事实推导结论的系统。MYCIN、DENDRAL、XCON 是 1980 年代的代表。' },
  { term: 'MYCIN', full: 'MYCIN', ch: 1, def: '1970 年代斯坦福大学开发的医学专家系统，用约 500 条规则诊断血液感染并推荐抗生素，是专家系统的标志性成果。' },
  { term: 'DENDRAL', full: 'DENDRAL', ch: 1, def: '早期的化学专家系统，根据质谱数据推断有机分子结构，被视为专家系统的先驱。' },
  { term: 'XCON', full: 'XCON', ch: 1, def: 'DEC 公司用于配置计算机订单的专家系统，1980 年代进入企业实际使用，推动知识工程形成产业。' },
  { term: 'Prospector', full: 'Prospector', ch: 1, def: '用于钼矿勘探的专家系统，根据地质数据评估矿藏可能性，是专家系统在资源勘探领域的代表。' },
  { term: '深蓝', full: 'Deep Blue', ch: 1, def: 'IBM 的国际象棋计算机，1997 年战胜世界冠军卡斯帕罗夫，依靠大规模搜索与专用硬件，而非神经网络。' },
  { term: 'ELIZA', full: 'ELIZA', ch: 1, def: '1966 年魏泽鲍姆编写的聊天程序，用关键词匹配与话术模板让人误以为它理解对话，常被用来说明图灵测试的局限。' },
  { term: 'Gato', full: 'Gato', ch: 1, def: 'DeepMind 的多任务智能体模型，用同一个网络完成数百项任务，是通用人工智能方向的探索性成果。' },
  { term: 'Whisper', full: 'Whisper', ch: 1, def: 'OpenAI 的语音识别模型，用大规模多语言音频训练，能把语音转成文字并支持翻译。' },
  { term: 'GPT-4V', full: 'GPT-4 with Vision', ch: 1, def: '支持图像输入的多模态大模型版本，可以看图回答问题、解析图表与数学题照片。' },
  { term: 'DeepSeek', full: 'DeepSeek', ch: 1, def: '中国的开源大模型系列，2025 年因推理能力与较低训练成本受到广泛关注。' },
  { term: '知识获取瓶颈', full: 'Knowledge Acquisition Bottleneck', ch: 1, def: '专家系统需要把专家头脑中的经验逐条写成规则，这个过程昂贵、缓慢且难以覆盖全部情况，成为符号主义的根本难题。' },
  { term: '组合爆炸', full: 'Combinatorial Explosion', ch: 1, def: '规则或搜索分支数量随问题规模指数增长，计算量迅速失控。符号主义系统在规则很多时尤其严重。' },
  { term: '数据饥渴', full: 'Data Hungry', ch: 1, def: '深度模型需要大量标注数据才能学好，数据不足时容易过拟合。它是联结主义路线的现实约束。' },
  { term: '黑箱', full: 'Black Box', ch: 1, def: '内部决策过程难以观察与解释的系统。深度神经网络通常被视为黑箱，输入与输出可见，中间推理不透明。' },
  { term: '知识工程', full: 'Knowledge Engineering', ch: 1, def: '把人类专家知识提取出来、表示成计算机可用的规则与结构的一整套方法，专家系统商业化时期形成产业。' },
  { term: '知识图谱', full: 'Knowledge Graph', ch: 1, def: '用「实体—关系—实体」三元组存储知识的结构化网络，例如「北京—是首都—中国」。它让机器能够检索和推理事实关系。' },
  { term: '感知机', full: 'Perceptron', ch: 1, def: '1957 年罗森布拉特提出的早期人工神经网络，只有一层可学习权重。它无法解决异或这类线性不可分问题，曾导致神经网络研究进入低潮。' },
  { term: '异或问题', full: 'XOR Problem', ch: 1, def: '两个输入不同时输出 1、相同时输出 0 的逻辑运算。单层感知机无法用一条直线把两类样本分开，因此解决不了它。' },
  { term: '反向传播', full: 'Back Propagation', alias: ['BP 算法', 'BP'], ch: 3, def: '利用链式法则从输出层向输入层逐层计算损失对每个参数的偏导数，再把梯度交给优化器更新权重。1986 年的论文让多层网络真正可训练。' },
  { term: '机器学习', full: 'Machine Learning', alias: ['ML'], ch: 2, def: '让计算机从数据中自动学得规律，并用新数据持续改进性能的方法。Mitchell 的定义是：任务 T、性能度量 P、经验 E，性能随 E 增加而改善。' },
  { term: '深度学习', full: 'Deep Learning', alias: ['DL'], ch: 3, def: '机器学习的分支，用多层神经网络自动学习从低级到高级的特征表示。它属于机器学习，机器学习属于人工智能。' },
  { term: '监督学习', full: 'Supervised Learning', ch: 2, def: '每条训练样本都带人工标注的答案 y，模型学习从输入 x 到输出 y 的映射。任务是分类或回归。' },
  { term: '无监督学习', full: 'Unsupervised Learning', ch: 2, def: '训练数据只有输入 x、没有人工标签，模型自行发现簇、低维结构、频繁模式或异常点。聚类与降维属于这一类。' },
  { term: '半监督学习', full: 'Semi-supervised Learning', ch: 2, def: '使用少量标注样本与大量未标注样本一起训练，利用未标注数据的分布结构提升泛化。医学影像标注昂贵时特别适用。' },
  { term: '自监督学习', full: 'Self-supervised Learning', ch: 2, def: '没有人工标签，由数据本身构造预测型辅助任务来产生监督信号，例如遮住句子中的词让模型猜、预测下一个词。BERT 与 GPT 的预训练都属于这一类。' },
  { term: '强化学习', full: 'Reinforcement Learning', alias: ['RL'], ch: 7, def: '智能体在环境中不断尝试动作，根据奖励与惩罚信号调整策略，目标是让长期累积奖励最大。它不需要人工标注正确动作。' },
  { term: '伪标签', full: 'Pseudo Labeling', ch: 2, def: '半监督学习的一种做法：先用少量标注数据训练模型，再用模型给未标注数据预测标签，把这些预测当作临时标签继续训练。预测错误会被放大。' },
  { term: '一致性正则', full: 'Consistency Regularization', ch: 2, def: '半监督学习中要求模型对同一输入的不同扰动版本给出一致预测的约束，借此利用未标注数据。' },
  { term: '掩码语言模型', full: 'Masked Language Model', alias: ['掩码预测', 'MLM'], ch: 5, def: '随机遮住输入中的一部分词元，让模型根据左右上下文预测被遮住的词。BERT 用它实现双向理解。' },
  { term: 'MAE', full: 'Masked Autoencoder', ch: 1, def: '掩码自编码器：随机遮住图像的大部分图块，让模型根据剩余图块重建缺失部分，属于自监督学习。它与平均绝对误差的缩写相同。' },
  { term: '对比学习', full: 'Contrastive Learning', ch: 2, def: '通过拉近相似样本的向量、推远不相似样本的向量来学习表示，不需要人工标签。SimCLR 是图像领域的代表。' },
  { term: '迁移学习', full: 'Transfer Learning', ch: 7, def: '把在一个任务或数据分布上学到的知识迁移到另一个任务，减少目标任务的训练数据与时间。预训练加微调是常见形式。' },
  { term: '联邦学习', full: 'Federated Learning', ch: 1, def: '多个参与方在本地训练模型，只上传参数更新而不共享原始数据，由中心聚合出全局模型，用来解决数据不出域的联合训练问题。' },
  { term: '集成学习', full: 'Ensemble Learning', ch: 2, def: '把多个基模型的预测组合起来，得到比单个模型更稳定、更准确的结果。Bagging 与随机森林属于这一类。' },
  { term: '预训练', full: 'Pretraining', ch: 6, def: '先在大规模通用数据上训练模型，让它学到语言的统计规律与通用表示，再用具体任务的数据做微调。' },
  { term: '微调', full: 'Fine-tuning', alias: ['Finetuning'], ch: 6, def: '在预训练模型的基础上，用领域数据继续训练，让通用能力适配具体任务。它会改变模型权重，需要重新训练。' },
  { term: '指令微调', full: 'Instruction Tuning', ch: 1, def: '用大量「指令—回答」样本继续训练预训练模型，让它学会按人类指令完成任务，提升零样本与少样本表现。' },
  { term: '多模态', full: 'Multimodal', ch: 4, def: '同时处理两种或更多信息形态，例如图像、文本、语音、视频、传感器信号。不同模态的表示方式不同，需要建立对应关系并融合推理。' },
  { term: '算力', full: 'Computing Power', ch: 1, def: '单位时间内完成计算的能力，通常用每秒浮点运算次数衡量。GPU、TPU、NPU 等芯片提供大规模并行计算，是训练大模型的基础条件。' },
  { term: '图形处理器', full: 'Graphics Processing Unit', alias: ['GPU'], ch: 1, def: '最初为图形渲染设计的并行计算芯片，拥有大量简单计算核心，适合矩阵运算，成为深度学习训练的主力硬件。' },
  { term: '张量处理单元', full: 'Tensor Processing Unit', alias: ['TPU'], ch: 1, def: '谷歌设计的专用人工智能加速芯片，针对张量运算优化，能效通常高于通用图形处理器。' },
  { term: '专用集成电路', full: 'Application-Specific Integrated Circuit', alias: ['ASIC'], ch: 1, def: '为特定任务定制的芯片，牺牲通用性换取更高能效与更低成本，人工智能推理芯片常采用这种路线。' },
  { term: '神经网络处理器', full: 'Neural Processing Unit', alias: ['NPU'], ch: 1, def: '专门加速神经网络运算的处理器，常见于手机与边缘设备，强调低功耗下的推理能力。' },
  { term: 'TFLOPS', full: 'Tera Floating-point Operations Per Second', ch: 1, def: '每秒万亿次浮点运算，用来衡量芯片的算力规模。数值越大代表单位时间能完成的计算越多。' },
  { term: '结构化数据', full: 'Structured Data', ch: 1, def: '按固定字段组织、可以直接存入表格或数据库的数据，例如订单记录、成绩表。' },
  { term: '非结构化数据', full: 'Unstructured Data', ch: 1, def: '没有固定字段结构的数据，例如文本、图像、音频、视频。它占数据总量的大多数，也是大模型训练的主要素材。' },
  { term: '过拟合', full: 'Overfitting', ch: 2, def: '模型把训练数据中的噪声也当成规律记住，训练集表现很好，换到没见过的数据就明显变差。常见对策是增加数据、正则化、Dropout、早停。' },
  { term: '表示学习', full: 'Representation Learning', ch: 1, def: '让模型自动学习如何把原始数据转换成有利于任务的向量表示，减少人工设计特征的依赖。深度学习的核心优势之一。' },
  { term: '端到端', full: 'End-to-End', ch: 7, def: '一个模型直接从原始输入得到最终输出，中间不拆分人工设计的模块，例如从摄像头图像直接输出方向盘转角。' },
  { term: '蒙特卡洛树搜索', full: 'Monte Carlo Tree Search', alias: ['MCTS'], ch: 1, def: '在巨大搜索空间中通过随机模拟评估候选分支、逐步把计算资源集中到有希望的分支上的算法，AlphaGo 用它配合策略网络与价值网络选点。' },
  { term: '自我对弈', full: 'Self-play', ch: 1, def: '让智能体与自己的不同版本对局，不断产生更高水平的训练数据。AlphaGo Zero 完全依靠自我对弈超越人类棋谱训练出的版本。' },
  { term: '策略网络', full: 'Policy Network', ch: 1, def: '输入当前局面、输出各个动作概率分布的神经网络，用来缩小搜索范围或直接决定动作。' },
  { term: '价值网络', full: 'Value Network', ch: 1, def: '输入局面、输出该局面胜负期望的神经网络，用来评估棋局优劣，减少无谓的搜索。' },
  { term: '深度强化学习', full: 'Deep Reinforcement Learning', alias: ['DQN'], ch: 1, def: '用深度神经网络表示强化学习中的策略或价值函数，使智能体能够从高维感知输入（如图像）直接学习决策。' },
  { term: 'ImageNet', full: 'ImageNet Large Scale Visual Recognition Challenge', ch: 1, def: '李飞飞等人组织的大规模图像数据集与竞赛，包含上千万张标注图片。2012 年 AlexNet 在竞赛中大幅降低错误率，引爆深度学习浪潮。' },
  { term: 'AlexNet', full: 'AlexNet', ch: 1, def: '2012 年 ImageNet 竞赛冠军模型，用卷积神经网络把错误率大幅降低，被视为深度学习第三次浪潮的起点。' },
  { term: '深度信念网络', full: 'Deep Belief Network', alias: ['DBN'], ch: 1, def: '2006 年 Hinton 提出的多层概率生成模型，用逐层无监督预训练加微调训练深层网络，开启深度学习序幕。' },
  { term: '生成对抗网络', full: 'Generative Adversarial Network', alias: ['GAN'], ch: 6, def: '由生成器与判别器组成的生成模型，生成器造假、判别器鉴真，两者交替训练，最终生成器能产出以假乱真的样本。' },
  { term: '控制论', full: 'Cybernetics', ch: 1, def: '维纳 1948 年提出的关于动物与机器中控制与通信的理论，强调反馈与自组织，是行为主义思想的源头之一。' },
  { term: 'LISP', full: 'List Processing', ch: 1, def: '1958 年麦卡锡设计的编程语言，以符号列表处理为核心，长期作为人工智能研究的首选语言。' },
  { term: '摩尔定律', full: "Moore's Law", ch: 1, def: '集成电路上可容纳的晶体管数量大约每两年翻一倍，性能随之提升、成本下降。它描述的是硬件发展的长期趋势，近年已经放缓。' },
  { term: '区块链', full: 'Blockchain', ch: 1, def: '由分布式账本、共识机制与密码学组成的不可篡改记录系统，解决多方互不信任时的记账问题，属于分布式系统与信息安全领域。' },
  { term: '计算机视觉', full: 'Computer Vision', alias: ['CV'], ch: 4, def: '让机器从图像与视频中获取、处理、理解信息的技术方向，包括分类、检测、分割、跟踪等任务。' },
  { term: '自然语言处理', full: 'Natural Language Processing', alias: ['NLP'], ch: 5, def: '让计算机理解、分析、处理、生成人类语言的技术方向，是人工智能与语言学的交叉领域。' },

  /* ---------- 第 2 章 ---------- */
  { term: '泛化', full: 'Generalization', alias: ['泛化能力'], ch: 2, def: '模型在没见过的数据上的表现。训练集分数高而测试集差，说明泛化能力不足，常见原因是过拟合。' },
  { term: '欠拟合', full: 'Underfitting', ch: 2, def: '模型过于简单或训练不足，连训练数据中的规律都没有学到，训练误差与测试误差都偏高。对策是增加特征、提高模型复杂度、延长训练。' },
  { term: '偏差', full: 'Bias', ch: 2, def: '模型假设与真实规律之间的系统性偏离。模型过于简单时偏差大，表现为欠拟合。' },
  { term: '方差', full: 'Variance', ch: 2, def: '换一批训练数据后模型预测结果的波动程度。模型过于复杂时方差大，表现为过拟合。' },
  { term: '正则化', full: 'Regularization', ch: 2, def: '在损失函数中加入惩罚项，限制参数过大，降低模型复杂度，从而抑制过拟合。岭回归与 Lasso 都是正则化方法。' },
  { term: 'Dropout', full: 'Dropout', ch: 3, def: '训练时按概率随机让一部分神经元暂时失效，迫使网络不依赖个别单元，是一种常用的正则化手段。推理阶段通常关闭。' },
  { term: '早停', full: 'Early Stopping', ch: 2, def: '在验证集误差开始上升时提前结束训练，避免模型继续拟合训练数据中的噪声。' },
  { term: '交叉验证', full: 'Cross Validation', ch: 2, def: '把数据分成若干折，轮流用其中一折做验证、其余做训练，最后平均各折结果，得到更稳定的性能估计。' },
  { term: '归一化', full: 'Normalization', ch: 2, def: '把数值按最小值与最大值线性缩放到 0 到 1 之间，公式为 (x−最小值)/(最大值−最小值)。它对异常值非常敏感。' },
  { term: '标准化', full: 'Standardization', ch: 2, def: '把数值减去均值再除以标准差，使结果均值为 0、标准差为 1。它对异常值的敏感度低于归一化。' },
  { term: '离群值', full: 'Outlier', alias: ['异常值'], ch: 2, def: '明显偏离其余样本的极端取值。它会把归一化结果压缩到很小的区间，也会影响均值与方差。' },
  { term: '量纲', full: 'Dimension', ch: 2, def: '物理量的单位与数量级，例如年收入用万元、年龄用岁。距离计算对量纲敏感，不同量纲的特征需要先缩放。' },
  { term: '欧氏距离', full: 'Euclidean Distance', ch: 2, def: '两点在各维差值的平方和再开方，即直线距离。K-means、KNN 默认使用它衡量样本相似度。' },
  { term: '最小二乘法', full: 'Ordinary Least Squares', alias: ['OLS'], ch: 2, def: '让残差平方和最小的参数估计方法。平方可以消除正负抵消、加重对大误差的惩罚，并且函数连续可导，有解析解。' },
  { term: '残差', full: 'Residual', ch: 2, def: '真实值减去模型预测值的差，即 e = y − ŷ。残差平方和是回归任务最常用的损失。' },
  { term: '正规方程', full: 'Normal Equation', ch: 2, def: '对最小二乘目标求偏导并令其为零得到的解析解公式，可以一次性算出最优参数，不需要迭代。' },
  { term: '梯度下降', full: 'Gradient Descent', ch: 3, def: '沿着损失函数负梯度方向逐步调整参数，使损失下降的优化方法。学习率决定每一步的步长。' },
  { term: '学习率', full: 'Learning Rate', ch: 3, def: '梯度下降每一步的步长。过大导致震荡甚至发散，过小导致收敛缓慢。' },
  { term: 'Xavier 初始化', full: 'Xavier Initialization', ch: 3, def: '按输入与输出神经元数量调整权重初始尺度的方案，让各层信号方差大致稳定。适合 Sigmoid 与 Tanh 网络。' },
  { term: 'He 初始化', full: 'He Initialization', ch: 3, def: '针对 ReLU 网络设计的权重初始化方案，放大初始方差以补偿 ReLU 把负半轴置零带来的信号衰减。' },
  { term: '对称性', full: 'Symmetry', ch: 3, def: '同一层神经元若权重完全相同，会得到相同梯度并始终同步更新，相当于只有一个神经元。全零初始化会触发这种问题。' },
  { term: 'CIFAR-10', full: 'CIFAR-10', ch: 3, def: '包含 10 类彩色小图的数据集，每类 6000 张，常用于评测图像分类模型。它属于规则网格数据，适合用卷积网络处理。' },
  { term: 'LightGCN', full: 'Light Graph Convolutional Network', ch: 3, def: '简化图卷积结构的推荐模型，去掉特征变换与非线性，只保留邻域聚合，在用户物品二部图上效果稳定。' },
  { term: '多重共线性', full: 'Multicollinearity', ch: 2, def: '多个自变量之间高度线性相关，导致回归系数方差变大、符号不稳定，t 检验不显著而整体 F 检验显著。' },
  { term: '方差膨胀因子', full: 'Variance Inflation Factor', alias: ['VIF'], ch: 2, def: '衡量某个自变量被其余自变量线性解释程度的指标。数值大于 10 通常认为存在严重多重共线性。' },
  { term: '岭回归', full: 'Ridge Regression', ch: 2, def: '在最小二乘目标中加入参数平方和惩罚的回归方法，能够压缩系数、缓解多重共线性。' },
  { term: 'Lasso', full: 'Least Absolute Shrinkage and Selection Operator', ch: 2, def: '在损失中加入参数绝对值之和惩罚的回归方法，可以把部分系数压到零，同时完成特征选择。' },
  { term: '异方差', full: 'Heteroscedasticity', ch: 2, def: '误差项的方差随自变量变化、不保持恒定。它会让标准误估计失真，区间估计与显著性检验不可靠。' },
  { term: '决定系数', full: 'Coefficient of Determination', alias: ['R²'], ch: 2, def: '回归模型解释掉的方差占因变量总方差的比例，越接近 1 拟合越好，取值也可以为负。' },
  { term: '均方误差', full: 'Mean Squared Error', alias: ['MSE'], ch: 2, def: '残差平方的平均值。它对大误差惩罚重，是回归任务常用的损失与评估指标。' },
  { term: '均方根误差', full: 'Root Mean Squared Error', alias: ['RMSE'], ch: 2, def: '均方误差开平方，量纲与因变量一致，便于解释误差的实际大小。' },
  { term: '平均绝对误差', full: 'Mean Absolute Error', alias: ['MAE'], ch: 2, def: '残差绝对值的平均。它比均方误差更不容易被极端值拉动。' },
  { term: '逻辑回归', full: 'Logistic Regression', ch: 2, def: '在线性组合外接 Sigmoid 得到概率的二分类模型。名字带回归，实际做的是分类，输出可以解释为属于正类的概率。' },
  { term: 'Sigmoid', full: 'Sigmoid Function', ch: 3, def: '把任意实数压缩到 0 到 1 之间的 S 形函数，公式为 1/(1+e^(−z))。它常用于二分类概率输出，导数最大只有 0.25，深层网络容易梯度消失。' },
  { term: '交叉熵', full: 'Cross Entropy', ch: 3, def: '衡量预测概率分布与真实分布差异的损失函数。分类任务常用它，预测越接近真实标签损失越小。' },
  { term: 'Softmax', full: 'Softmax Function', ch: 3, def: '把一组实数转换成总和为 1 的概率分布，多分类任务的输出层常用它。' },
  { term: 'One-vs-Rest', full: 'One-vs-Rest', ch: 2, def: '多分类策略：为每个类别训练一个二分类器，判断样本是否属于该类，最后取概率最高的类别。' },
  { term: '阈值', full: 'Threshold', ch: 2, def: '把连续概率切成类别判定时使用的分界值。阈值提高会减少误报但增加漏报，阈值降低则相反。' },
  { term: '混淆矩阵', full: 'Confusion Matrix', ch: 2, def: '按真实类别与预测类别交叉统计的表格，包含真正例、假正例、假负例、真负例四个格子，是分类指标的来源。' },
  { term: '真正例', full: 'True Positive', alias: ['TP'], ch: 2, def: '真实为正类、预测也为正类的样本，即判对了的正类。' },
  { term: '假正例', full: 'False Positive', alias: ['FP'], ch: 2, def: '真实为负类、却被预测为正类的样本，也就是误报。' },
  { term: '假负例', full: 'False Negative', alias: ['FN'], ch: 2, def: '真实为正类、却被预测为负类的样本，也就是漏报。' },
  { term: '真负例', full: 'True Negative', alias: ['TN'], ch: 2, def: '真实为负类、预测也为负类的样本，即判对了的负类。' },
  { term: '准确率', full: 'Accuracy', ch: 2, def: '(TP+TN)/总数，表示整体判对的比例。类别极不均衡时它会高估模型性能。' },
  { term: '精确率', full: 'Precision', ch: 2, def: 'TP/(TP+FP)，表示预测为正的样本里真正为正的比例。怕误报的场景优先看它。' },
  { term: '召回率', full: 'Recall', ch: 2, def: 'TP/(TP+FN)，表示实际为正的样本里被找出来的比例。怕漏报的场景优先看它。' },
  { term: 'F1 分数', full: 'F1 Score', alias: ['F1'], ch: 2, def: '精确率与召回率的调和平均，公式为 2PR/(P+R)。两者相差越大，F1 被拉得越低。' },
  { term: '宏平均', full: 'Macro Average', ch: 2, def: '先分别计算每个类别的指标，再对所有类别取算术平均。每个类别权重相同，小类不会被大类淹没。' },
  { term: '加权平均', full: 'Weighted Average', ch: 2, def: '按每个类别的样本数量加权后再平均。样本多的类别对结果影响更大。' },
  { term: 'ROC 曲线', full: 'Receiver Operating Characteristic Curve', alias: ['ROC'], ch: 2, def: '以假正例率为横轴、真正例率为纵轴，在不同阈值下画出的曲线，用来观察模型区分正负类的能力。' },
  { term: 'AUC', full: 'Area Under Curve', ch: 2, def: 'ROC 曲线下的面积，越接近 1 越好，0.5 相当于随机猜测。它不受类别比例影响，适合不均衡数据。' },
  { term: 'PR 曲线', full: 'Precision-Recall Curve', ch: 2, def: '以召回率为横轴、精确率为纵轴画出的曲线，正样本极少时比 ROC 曲线更能反映模型表现。' },
  { term: 'SMOTE', full: 'Synthetic Minority Over-sampling Technique', ch: 2, def: '在少数类样本之间插值合成新样本的过采样方法，用来缓解类别不平衡。' },
  { term: '分层抽样', full: 'Stratified Sampling', ch: 2, def: '按类别比例分别抽取训练集与测试集，保证两边类别分布一致，避免某一类在某一侧过少。' },
  { term: '类别不平衡', full: 'Class Imbalance', ch: 2, def: '不同类别的样本数量差距悬殊，例如正常短信 990 条、垃圾短信 10 条。此时准确率会高估性能，需要改用精确率、召回率或 F1。' },
  { term: 'K 近邻', full: 'K-Nearest Neighbors', alias: ['KNN'], ch: 2, def: '监督学习算法：找出距离新样本最近的 K 个已标注样本，由它们投票决定类别或取平均值。它需要先缩放特征，预测时计算量大。' },
  { term: 'K-means', full: 'K-means Clustering', alias: ['K 均值聚类'], ch: 2, def: '无监督聚类算法：先指定簇数 K，反复执行「把样本分到最近的中心」与「把中心移到簇内均值」，直到中心稳定。目标是簇内平方误差和最小。' },
  { term: '簇', full: 'Cluster', ch: 2, def: '聚类算法把相似样本归在一起形成的一组。簇号通常从 0 开始编号，K 个簇对应 0 到 K−1。' },
  { term: '质心', full: 'Centroid', ch: 2, def: '一个簇中所有样本的均值向量，K-means 用它代表簇的位置，并在更新步移动到新的均值处。' },
  { term: '肘部法则', full: 'Elbow Method', ch: 2, def: '画出簇内平方误差和随 K 变化的曲线，选择下降速度明显变缓的拐点作为簇数。' },
  { term: 'K-means++', full: 'K-means++', ch: 2, def: '选择初始中心时让它们彼此尽量远离的改进方法，能降低收敛到较差局部最优的概率。' },
  { term: '曼哈顿距离', full: 'Manhattan Distance', ch: 2, def: '各维差值绝对值之和，像在棋盘上只能沿横竖方向行走的距离。使用它时 K-means 的最优中心变成中位数。' },
  { term: '余弦相似度', full: 'Cosine Similarity', ch: 2, def: '用两个向量的夹角余弦衡量方向上的相似程度，对向量长度不敏感，适合文本与高维稀疏数据。' },
  { term: 'K-medians', full: 'K-medians', ch: 2, def: '把 K-means 的距离换成曼哈顿距离、把中心换成中位数的聚类方法，对离群值更稳健。' },
  { term: 'K-medoids', full: 'K-medoids', ch: 2, def: '用真实样本点作为簇代表的聚类方法，对离群值不敏感。' },
  { term: 'DBSCAN', full: 'Density-Based Spatial Clustering of Applications with Noise', ch: 2, def: '基于密度的聚类算法，把高密度区域连成簇，并能把低密度区域的点标为噪声。它不需要预先指定簇数，能发现非球形簇。' },
  { term: '层次聚类', full: 'Hierarchical Clustering', ch: 2, def: '通过不断合并或拆分簇形成树状结构，可以按不同高度切出不同数量的簇，不需要预先指定 K。' },
  { term: '决策树', full: 'Decision Tree', ch: 2, def: '按特征逐层提问、把样本分到叶节点的分类或回归模型。每个叶节点代表一种类别，规则直观、可解释性强。' },
  { term: '信息熵', full: 'Information Entropy', ch: 2, def: '衡量一组样本类别混乱程度的指标，熵越大越混乱。决策树选择让划分后熵下降最多的特征。' },
  { term: '信息增益', full: 'Information Gain', ch: 2, def: '划分前的熵减去划分后各子集熵的加权平均。增益越大，说明该特征带来的纯度提升越多。' },
  { term: '随机森林', full: 'Random Forest', ch: 2, def: '训练多棵决策树并投票的集成模型。每棵树使用随机抽取的样本与随机抽取的特征子集，降低单棵树的不稳定性。' },
  { term: 'Bagging', full: 'Bootstrap Aggregating', ch: 2, def: '有放回地抽取多份训练子集，分别训练模型再投票或平均的集成方法，主要作用是降低方差。' },
  { term: '朴素贝叶斯', full: 'Naive Bayes', ch: 2, def: '基于贝叶斯公式的分类器，假设各特征在给定类别下条件独立。假设通常不成立，但计算量小，文本分类效果往往不错。' },
  { term: '先验概率', full: 'Prior Probability', ch: 2, def: '看到新证据之前对某个类别的信念，即 P(C)。' },
  { term: '后验概率', full: 'Posterior Probability', ch: 2, def: '结合证据之后对类别的更新判断，即 P(C|X)。贝叶斯公式用先验与似然算出它。' },
  { term: '条件概率', full: 'Conditional Probability', ch: 2, def: '在已知某事件发生的条件下，另一事件发生的概率，记作 P(A|B)。' },
  { term: '条件独立', full: 'Conditional Independence', ch: 2, def: '在给定类别的前提下，各特征之间互不影响。朴素贝叶斯的「朴素」就来自这个假设。' },
  { term: '皮尔逊相关系数', full: 'Pearson Correlation Coefficient', ch: 2, def: '衡量两个变量线性相关程度的数值，取值在 −1 到 1 之间。绝对值看强弱，符号看方向。' },
  { term: '混杂变量', full: 'Confounder', ch: 2, def: '同时影响自变量与因变量的第三个变量，会让两者看起来相关。冰淇淋销量与溺水人数同升，共同原因是气温。' },
  { term: '因果关系', full: 'Causality', ch: 2, def: '一个变量的变化直接导致另一个变量变化的关系。相关性只能说明同步变化，不能直接推出因果。' },
  { term: '独热编码', full: 'One-hot Encoding', ch: 2, def: '把 m 个无序类别展开成 m 列 0/1，每行只有一个 1。它避免引入虚假的大小顺序，代价是维度升高。' },
  { term: '序数编码', full: 'Ordinal Encoding', ch: 2, def: '把每个类别映射成一个整数，只占一列。它适合本身有顺序的类别，用在无序类别上会强加距离。' },
  { term: '名义变量', full: 'Nominal Variable', ch: 2, def: '取值之间没有大小顺序的类别变量，例如地区、颜色、品牌，适合用独热编码。' },
  { term: '特征哈希', full: 'Feature Hashing', ch: 2, def: '用哈希函数把大量类别映射到固定数量的维度，节省内存，代价是可能发生哈希冲突。' },
  { term: '虚拟变量陷阱', full: 'Dummy Variable Trap', ch: 2, def: '独热编码保留全部 m 列时，各列之和恒为 1，与截距项完全共线。通常删掉一列来避免。' },
  { term: '目标编码', full: 'Target Encoding', ch: 2, def: '用每个类别对应的目标均值代替类别本身，适合高基数类别特征，需要防止标签泄露。' },
  { term: '标准差', full: 'Standard Deviation', ch: 2, def: '各数值与均值之差的平方平均后再开方，衡量数据的离散程度。标准化用它做分母。' },
  { term: '正态分布', full: 'Normal Distribution', ch: 2, def: '钟形对称的连续概率分布，由均值与标准差决定。许多统计方法假设误差项近似正态。' },
  { term: '簇内平方误差和', full: 'Sum of Squared Errors', alias: ['SSE'], ch: 2, def: '每个样本到所属簇中心距离平方的总和，K-means 直接最小化这个目标。' },
  { term: '损失函数', full: 'Loss Function', ch: 3, def: '衡量模型预测与真实答案差距的函数，训练的目标就是让它尽可能小。回归常用均方误差，分类常用交叉熵。' },
  { term: '目标函数', full: 'Objective Function', ch: 2, def: '训练过程中要优化的函数，通常是损失函数加上正则项。K-means 的目标函数是簇内平方误差和。' },
  { term: '特征选择', full: 'Feature Selection', ch: 2, def: '从原始特征中挑出对任务有用的子集，去掉冗余与无关特征，降低过拟合风险并提升训练速度。' },
  { term: '训练集', full: 'Training Set', ch: 2, def: '用来调整模型参数的数据集合。模型在它上面的表现不能代表泛化能力。' },
  { term: '测试集', full: 'Test Set', ch: 2, def: '训练过程中完全不使用的数据集合，用来估计模型在没见过的数据上的真实表现。' },
  { term: 'Mechanical Turk', full: 'Amazon Mechanical Turk', ch: 2, def: '亚马逊的众包任务平台，把大量标注工作拆成小任务分给全球参与者，ImageNet 就是借助它完成大规模标注的。' },
  { term: '鸢尾花数据集', full: 'Iris Dataset', ch: 2, def: '经典的机器学习数据集，包含 150 条鸢尾花样本、3 个品种、4 个特征，常用于演示分类与聚类。' },

  /* ---------- 第 3 章 ---------- */
  { term: '人工神经元', full: 'Artificial Neuron', ch: 3, def: '神经网络的基本单元：接收多个输入，各自乘以权重后求和、加上偏置，再经过激活函数输出。' },
  { term: '激活函数', full: 'Activation Function', ch: 3, def: '在神经元加权求和之后施加的非线性函数，让网络能够拟合复杂关系。常见的有 Sigmoid、Tanh、ReLU。' },
  { term: '权重', full: 'Weight', ch: 3, def: '模型中可学习的系数，表示某个输入或连接对输出的影响强度。训练过程不断调整权重，让模型输出更接近正确答案。' },
  { term: '偏置', full: 'Bias', ch: 3, def: '加在加权和上的常数项，让神经元在输入全为零时也能有非零输出，相当于平移激活函数。' },
  { term: '输入层', full: 'Input Layer', ch: 3, def: '神经网络接收原始数据的层，神经元数量通常等于输入特征的维度。' },
  { term: '隐藏层', full: 'Hidden Layer', ch: 3, def: '输入层与输出层之间的层，逐层把低级特征组合成高级特征。层数越多，网络的表示能力越强。' },
  { term: '输出层', full: 'Output Layer', ch: 3, def: '神经网络给出最终结果的层。回归任务输出连续值，分类任务输出类别分数或概率。' },
  { term: '前馈神经网络', full: 'Feedforward Neural Network', ch: 3, def: '数据从输入层经隐藏层流向输出层、没有反馈连接的最基础神经网络。' },
  { term: '前向传播', full: 'Forward Propagation', ch: 3, def: '输入数据逐层经过加权求和与激活函数，最终得到预测值的过程。' },
  { term: '链式法则', full: 'Chain Rule', ch: 3, def: '微积分中求复合函数导数的法则。反向传播用它把输出层的误差逐层传回，计算每个参数的梯度。' },
  { term: '梯度', full: 'Gradient', ch: 3, def: '损失函数对参数求偏导得到的向量，指向损失上升最快的方向。参数沿负梯度方向移动才能让损失下降。' },
  { term: '优化器', full: 'Optimizer', ch: 3, def: '根据梯度更新模型参数的算法，例如 SGD、Adam。反向传播只负责算梯度，更新参数由优化器完成。' },
  { term: '随机梯度下降', full: 'Stochastic Gradient Descent', alias: ['SGD'], ch: 3, def: '每次只用一小批样本估计梯度并更新参数，比用全量数据计算更快，是深度学习的常用优化方法。' },
  { term: 'Adam', full: 'Adaptive Moment Estimation', ch: 3, def: '结合动量与自适应学习率的优化器，为每个参数单独调整步长，收敛快、调参压力小。' },
  { term: '梯度消失', full: 'Vanishing Gradient', ch: 3, def: '反向传播时梯度逐层连乘后越来越小，靠前的层几乎无法更新。Sigmoid 导数最大只有 0.25 是典型诱因，ReLU、残差连接、LSTM 可以缓解。' },
  { term: '梯度爆炸', full: 'Exploding Gradient', ch: 3, def: '反向传播时梯度逐层连乘后越来越大，参数更新剧烈甚至溢出。对策是梯度裁剪、权重正则与合理初始化。' },
  { term: '梯度裁剪', full: 'Gradient Clipping', ch: 3, def: '当梯度范数超过设定阈值时按比例缩小，防止梯度爆炸。它对梯度消失没有作用。' },
  { term: '批归一化', full: 'Batch Normalization', alias: ['批量归一化'], ch: 3, def: '在每个小批次上对中间层输出做标准化，稳定数据分布、加速收敛。它不改变张量形状。' },
  { term: '残差连接', full: 'Residual Connection', ch: 3, def: '把某层的输入直接加到输出上，让梯度有一条捷径回传，使很深的网络仍然可训练。' },
  { term: '门控', full: 'Gating', ch: 3, def: '用 0 到 1 的系数控制信息保留多少的机制。LSTM 与 GRU 通过门决定记住、写入或输出哪些信息。' },
  { term: '细胞状态', full: 'Cell State', ch: 3, def: 'LSTM 中沿时间步传递的主干信息通道，更新方式以加法为主，使梯度可以近乎无损地回传。' },
  { term: '遗忘门', full: 'Forget Gate', ch: 3, def: 'LSTM 中决定上一时刻细胞状态保留多少的门，输出接近 1 表示保留，接近 0 表示遗忘。' },
  { term: '输入门', full: 'Input Gate', ch: 3, def: 'LSTM 中决定当前候选信息写入细胞状态多少的门。' },
  { term: '输出门', full: 'Output Gate', ch: 3, def: 'LSTM 中决定细胞状态有多少输出到隐藏状态的门。' },
  { term: 'LSTM', full: 'Long Short-Term Memory', alias: ['长短期记忆网络'], ch: 3, def: '带细胞状态与三个门的循环神经网络变体，能缓解梯度消失、建模长期依赖。代价是参数多、计算慢。' },
  { term: 'GRU', full: 'Gated Recurrent Unit', alias: ['门控循环单元'], ch: 3, def: 'LSTM 的简化版本，用更新门与重置门合并细胞状态与隐藏状态，参数更少、训练更快。' },
  { term: 'Tanh', full: 'Hyperbolic Tangent', ch: 3, def: '把实数压缩到 −1 到 1 的双曲正切函数，输出以零为中心。导数最大为 1，两端仍会饱和。' },
  { term: 'ReLU', full: 'Rectified Linear Unit', alias: ['修正线性单元'], ch: 3, def: '输入大于零时原样输出、小于零时输出零的激活函数，正区间导数恒为 1，能有效缓解梯度消失。' },
  { term: 'Leaky ReLU', full: 'Leaky Rectified Linear Unit', ch: 3, def: '负半轴保留一个小斜率的 ReLU 变体，避免神经元在负区间完全不更新。' },
  { term: '死亡 ReLU', full: 'Dying ReLU', ch: 3, def: '某个神经元长期落在负区间、梯度恒为零，参数再也无法更新的现象。Leaky ReLU 可以缓解。' },
  { term: 'MNIST', full: 'Modified National Institute of Standards and Technology', ch: 3, def: '手写数字图像数据集，包含 0 到 9 的灰度图片，常用来演示神经网络分类流程。' },
  { term: '神经网络', full: 'Neural Network', alias: ['人工神经网络', 'ANN'], ch: 3, def: '由大量人工神经元分层连接而成的计算模型，通过调整连接权重从数据中学习规律。多层结构构成深度神经网络。' },
  { term: '卷积神经网络', full: 'Convolutional Neural Network', alias: ['CNN'], ch: 3, def: '用卷积层提取局部特征、池化层压缩尺寸、全连接层完成分类的网络，擅长处理图像等网格结构数据。' },
  { term: '循环神经网络', full: 'Recurrent Neural Network', alias: ['RNN'], ch: 3, def: '隐藏状态沿时间步传递的网络，能够处理变长序列并保留历史信息，常用于文本与语音。' },
  { term: '图神经网络', full: 'Graph Neural Network', alias: ['GNN'], ch: 3, def: '在图结构上做邻域聚合与特征变换的网络，适合社交网络、分子结构、推荐系统等不规则拓扑数据。' },
  { term: 'Transformer', full: 'Transformer', ch: 3, def: '完全基于自注意力的序列模型，抛弃循环与卷积，可以并行处理整个序列，是 BERT、GPT 与大语言模型的共同基础。' },
  { term: '卷积', full: 'Convolution', ch: 3, def: '用一个小矩阵在输入上滑动，逐位置做加权求和，得到特征图。它擅长捕捉局部模式，并大幅减少参数量。' },
  { term: '卷积核', full: 'Convolution Kernel', ch: 3, def: '卷积层中可学习的小矩阵，例如 3×3、5×5。它的深度必须与输入通道数一致，每个核生成一张特征图。' },
  { term: '特征图', full: 'Feature Map', ch: 3, def: '卷积核扫过输入后生成的二维响应图，表示某种特征在空间各位置的强弱。' },
  { term: '局部感受野', full: 'Local Receptive Field', ch: 3, def: '卷积层中每个输出位置只连接输入的一小块区域，对应图像中相邻像素关系紧密的先验。' },
  { term: '权值共享', full: 'Weight Sharing', ch: 3, def: '同一个卷积核在整张图上滑动并重复使用同一组权重，使参数量与图像分辨率无关，并带来平移等变性。' },
  { term: '平移不变性', full: 'Translation Invariance', ch: 3, def: '同一个模式出现在图像的不同位置时，网络仍能识别出来。局部连接、权值共享与池化共同带来这一性质。' },
  { term: '池化', full: 'Pooling', ch: 3, def: '在小窗口内做最大值或平均值，降低特征图的空间尺寸，增强鲁棒性并减少计算。它不改变通道数。' },
  { term: '最大池化', full: 'Max Pooling', ch: 3, def: '取窗口内最大值，保留最显著的特征响应，是卷积网络最常用的下采样方式。' },
  { term: '平均池化', full: 'Average Pooling', ch: 3, def: '取窗口内平均值，平滑特征响应，可能弱化局部显著信息。' },
  { term: '全连接层', full: 'Fully Connected Layer', ch: 3, def: '每个输入单元与每个输出单元都相连的层，把特征图展平后组合成高级特征并映射到类别或数值。参数量通常很大。' },
  { term: '展平', full: 'Flatten', ch: 3, def: '把三维特征图按固定顺序展开成一维向量，以便送入全连接层。' },
  { term: '填充', full: 'Padding', ch: 3, def: '在输入边缘补零或补值，控制卷积后特征图的空间尺寸。3×3 核配 1 圈填充可以保持尺寸不变。' },
  { term: '步长', full: 'Stride', ch: 3, def: '卷积核每次滑动的像素距离。步长大于 1 会降低输出尺寸，起到下采样作用。' },
  { term: '张量', full: 'Tensor', ch: 3, def: '多维数组的统称。标量是零维张量，向量是一维，图像是三维（高、宽、通道），视频加时间维。' },
  { term: 'same 卷积', full: 'Same Convolution', ch: 3, def: '通过合适的填充让卷积输出与输入的空间尺寸保持一致。3×3 核、步长 1 时填充设为 1。' },
  { term: '数据增强', full: 'Data Augmentation', ch: 3, def: '对训练图像做旋转、裁剪、翻转、变色等随机变换，扩充样本多样性，减少过拟合。' },
  { term: '参数量', full: 'Parameter Count', ch: 3, def: '模型中需要学习的权重与偏置的总数。卷积层的参数量只与核大小、输入通道数、核个数有关。' },
  { term: '隐藏状态', full: 'Hidden State', ch: 3, def: '循环神经网络在每个时间步保存并传给下一步的内部表示，压缩了此前输入的历史信息。' },
  { term: '时间步', full: 'Time Step', ch: 3, def: '序列中的一个位置。循环网络按时间步依次处理输入，并在步与步之间传递隐藏状态。' },
  { term: '变长序列', full: 'Variable-length Sequence', ch: 3, def: '长度不固定的输入序列，例如长短不一的句子。循环网络配合填充与掩码可以处理。' },
  { term: 'BPTT', full: 'Backpropagation Through Time', ch: 3, def: '把循环网络按时间步展开成深层网络，再用反向传播计算梯度的算法。所有时间步共享同一组权重，梯度对各步求和。' },
  { term: '双向循环神经网络', full: 'Bidirectional RNN', alias: ['Bi-RNN'], ch: 3, def: '用前向与后向两个循环网络分别处理序列，再把输出拼接，使每个位置同时利用过去与未来的上下文。' },
  { term: '词性标注', full: 'Part-of-Speech Tagging', alias: ['POS'], ch: 5, def: '为句子中的每个词标出名词、动词、形容词等语法类别，是句法分析的基础任务。' },
  { term: '命名实体识别', full: 'Named Entity Recognition', alias: ['NER'], ch: 5, def: '从文本中找出人名、地名、机构名、时间、数量等实体并分类，常用 BIO 序列标注配合 BiLSTM-CRF。' },
  { term: '图卷积网络', full: 'Graph Convolutional Network', alias: ['GCN'], ch: 3, def: '在图结构上做卷积的神经网络：每个节点聚合邻居特征，再做线性变换与非线性激活，适合邻居数量不固定的数据。' },
  { term: '邻域聚合', full: 'Neighborhood Aggregation', ch: 3, def: '图神经网络中把节点自身与邻居节点的特征按平均、求和或拼接等方式合并的步骤。' },
  { term: '拓扑', full: 'Topology', ch: 3, def: '节点与连接关系的整体结构。图数据具有不规则拓扑，每个节点的邻居数量可以不同。' },
  { term: '二部图', full: 'Bipartite Graph', ch: 3, def: '节点可以分成两个集合、边只连接两个集合之间的图，例如用户与物品的交互关系。' },
  { term: 'Cora 数据集', full: 'Cora Dataset', ch: 3, def: '论文引用网络数据集，节点是论文、边是引用关系、特征是论文词向量，常用来评测图神经网络节点分类。' },
  { term: '注意力机制', full: 'Attention Mechanism', ch: 3, def: '根据当前需求为不同输入位置分配不同权重的机制，让模型把计算资源集中在相关信息上。' },
  { term: '自注意力', full: 'Self-Attention', ch: 3, def: '序列中的每个位置与同一序列的所有位置直接计算相关性并加权汇总，任意两个位置的信息路径长度为常数，适合长距离依赖。' },
  { term: '查询键值', full: 'Query, Key, Value', alias: ['Q/K/V', 'QKV'], ch: 3, def: '自注意力的三组向量：查询表示当前要找什么，键表示各位置能提供什么，值是被加权汇总的内容。' },
  { term: '多头注意力', full: 'Multi-Head Attention', ch: 3, def: '用多组独立的查询、键、值投影并行计算注意力，再拼接结果，让模型在不同子空间同时关注语法、指代、语义等关系。' },
  { term: '位置编码', full: 'Positional Encoding', ch: 3, def: '给每个词元加入表示先后位置的信息，弥补自注意力本身不感知顺序的缺陷。原始 Transformer 用正弦余弦函数。' },
  { term: '编码器', full: 'Encoder', ch: 3, def: '把输入序列转换成特征表示的模块。在循环网络中它把整句压缩成状态；在 Transformer 中由自注意力与前馈网络堆叠而成。另外，测量电机转速的传感器也叫编码器。' },
  { term: '解码器', full: 'Decoder', ch: 3, def: '根据编码器的输出逐步生成目标序列的模块，生成时使用因果掩码，防止看到未来的词元。' },
  { term: '编码器解码器注意力', full: 'Encoder-Decoder Attention', ch: 3, def: '解码器中对编码器输出做注意力的模块，让每一步生成都能动态关注源句的相关部分，常用于机器翻译。' },
  { term: '前馈网络', full: 'Feed Forward Network', ch: 3, def: 'Transformer 每层中的两层全连接网络，对每个位置独立做非线性变换，增强表示能力。' },
  { term: '置换等变', full: 'Permutation Equivariance', ch: 3, def: '输入顺序改变时，输出只是按相同顺序重新排列。自注意力本身具有这一性质，因此需要位置编码补充顺序信息。' },
  { term: 'RoPE', full: 'Rotary Position Embedding', ch: 3, def: '旋转位置编码，用旋转矩阵把位置信息作用到查询与键上，能让模型外推到更长的序列。' },
  { term: 'ALiBi', full: 'Attention with Linear Biases', ch: 3, def: '一种位置编码方案，直接给注意力分数加上与距离成正比的线性偏置，实现简单且利于长度外推。' },
  { term: 'Video Transformer', full: 'Video Transformer', ch: 3, def: '把视频切成时空块后直接做自注意力的模型，能同时建模空间与时间关系。' },
  { term: '视觉 Transformer', full: 'Vision Transformer', alias: ['ViT'], ch: 3, def: '把图像切成小块当作词元序列、用 Transformer 编码器做图像分类的结构。' },
  { term: 'Conformer', full: 'Convolution-augmented Transformer', ch: 3, def: '把卷积与 Transformer 结合的语音模型结构，兼顾局部声学特征与全局上下文。' },
  { term: '3D 卷积神经网络', full: '3D Convolutional Neural Network', alias: ['3D CNN'], ch: 3, def: '在高度、宽度、时间三个方向同时做卷积的网络，用于视频等时空数据。' },
  { term: 'CNN+LSTM', full: 'CNN+LSTM', ch: 3, def: '用卷积网络逐帧提取空间特征，再把特征序列送入 LSTM 建模时间关系的视频理解架构。' },

  /* ---------- 第 4 章 ---------- */
  { term: '像素', full: 'Pixel', ch: 4, def: '构成数字图像的最小方格，每个像素携带自己的颜色信息。图像在计算机中就是像素值组成的矩阵。' },
  { term: '分辨率', full: 'Resolution', ch: 4, def: '图像在空间上的采样密度，通常写成宽×高像素数，例如 1920×1080。分辨率越高，记录的细节越多，计算与存储开销也越大。' },
  { term: 'PPI', full: 'Pixels Per Inch', ch: 4, def: '每英寸包含的像素数，用来描述显示或扫描设备的像素密度。' },
  { term: 'DPI', full: 'Dots Per Inch', ch: 4, def: '每英寸点数，常用于描述打印设备的墨点密度。它与 PPI 经常被混用，含义侧重点不同。' },
  { term: '位深', full: 'Bit Depth', ch: 4, def: '每个颜色通道用多少位表示。8 位对应 256 个等级，三个通道共 24 位，可表示约 1677 万种颜色。' },
  { term: '压缩比', full: 'Compression Ratio', ch: 4, def: '原始数据量与压缩后数据量的比值，由编码算法与质量参数决定，例如 JPEG 的质量因子。' },
  { term: 'JPEG', full: 'Joint Photographic Experts Group', ch: 4, def: '常用的有损图像压缩标准，利用人眼对亮度与色度敏感度不同来丢弃部分信息，压缩率高但细节会损失。' },
  { term: '加色模型', full: 'Additive Color Model', ch: 4, def: '通过叠加不同强度的色光产生颜色，红绿蓝全开得到白色，全关得到黑色。显示器与摄像头传感器使用这种模型。' },
  { term: '减色模型', full: 'Subtractive Color Model', ch: 4, def: '通过吸收部分色光产生颜色，青、品红、黄、黑墨水叠加越多颜色越深。印刷使用这种模型。' },
  { term: '色差', full: 'Color Difference', ch: 4, def: '两种颜色在感知上的差异程度。LAB 等设备无关的色彩空间专门用来计算色差。' },
  { term: '插值', full: 'Interpolation', ch: 4, def: '根据已知点的数值推算未知点的数值。图像放大用它补齐新增像素，不会凭空产生原图没有的细节；生成模型也会在潜在空间中做插值来过渡两种结果。' },
  { term: '下采样', full: 'Downsampling', ch: 4, def: '降低图像或特征图的空间尺寸，减少计算量与存储开销，可以通过池化、步长卷积或直接缩小分辨率实现。' },
  { term: '光学字符识别', full: 'Optical Character Recognition', alias: ['OCR'], ch: 4, def: '把图像中的文字区域识别成可编辑文本的技术，高分辨率图像能提供更清晰的笔画细节。' },
  { term: '颜色直方图', full: 'Color Histogram', ch: 4, def: '统计图像中各颜色或各通道取值出现次数的分布，用来描述整体色调，计算简单但丢失空间位置。' },
  { term: '纹理特征', full: 'Texture Feature', ch: 4, def: '描述图像表面重复模式、粗糙度、方向性与疏密的特征，常用于区分树皮、丝绸、草地等材质。' },
  { term: '局部二值模式', full: 'Local Binary Pattern', alias: ['LBP'], ch: 4, def: '比较中心像素与周围像素大小并编码成二进制数的纹理描述子，计算简单、对光照变化有一定鲁棒性。' },
  { term: '灰度共生矩阵', full: 'Gray Level Co-occurrence Matrix', alias: ['GLCM'], ch: 4, def: '统计图像中相距一定位移的像素对灰度组合出现频率的矩阵，从中可以算出对比度、能量、熵等纹理指标。' },
  { term: 'Gabor 滤波', full: 'Gabor Filter', ch: 4, def: '由正弦波与高斯包络相乘构成的滤波器，对特定方向与频率的纹理响应强烈，常用于纹理分析。' },
  { term: '形状特征', full: 'Shape Feature', ch: 4, def: '描述物体外形的特征，例如轮廓、角点、面积、长宽比、矩不变量。' },
  { term: 'Hu 矩', full: 'Hu Moments', ch: 4, def: '由图像矩组合而成的一组特征，对平移、缩放与旋转不敏感，常用于形状匹配。' },
  { term: '边缘特征', full: 'Edge Feature', ch: 4, def: '图像中灰度剧烈变化的位置，通常对应物体的轮廓与结构分界。' },
  { term: 'Sobel 算子', full: 'Sobel Operator', ch: 4, def: '用两个方向的小卷积核近似计算图像梯度，检测水平与垂直边缘，计算简单但对噪声敏感。' },
  { term: 'Canny 算子', full: 'Canny Edge Detector', ch: 4, def: '多阶段边缘检测算法：高斯平滑、计算梯度、非极大值抑制、双阈值连接，边缘定位准确且较细。' },
  { term: '高斯拉普拉斯', full: 'Laplacian of Gaussian', alias: ['LoG'], ch: 4, def: '先做高斯平滑再求二阶导的算子，用于检测边缘与斑点。尺度参数越大，检测到的结构越粗。' },
  { term: '滤波器', full: 'Filter', ch: 4, def: '对图像做加权运算的算子，用一个小窗口逐位置计算，用来强化边缘、纹理或抑制噪声。LoG 与 Gabor 都属于滤波器。' },
  { term: 'σ', full: 'Sigma', ch: 4, def: 'LoG 滤波器的高斯尺度参数，控制平滑与特征粗细。σ 小对细节敏感但怕噪声，σ 大抗噪但会模糊细节。' },
  { term: '图像分类', full: 'Image Classification', ch: 4, def: '判断整张图像属于哪个类别，输出一个类别标签。它不给出物体位置。' },
  { term: '目标检测', full: 'Object Detection', ch: 4, def: '同时判断图像中有什么物体以及它们在哪里，输出类别标签、置信度与边界框。' },
  { term: '语义分割', full: 'Semantic Segmentation', ch: 4, def: '为每个像素分配一个类别，不区分同一类别的不同个体。两辆并排的出租车会连成一片。' },
  { term: '实例分割', full: 'Instance Segmentation', ch: 4, def: '为每个像素分配类别并区分个体，输出逐像素掩码与实例编号，能分出车-1、车-2。' },
  { term: '全景分割', full: 'Panoptic Segmentation', ch: 4, def: '语义分割与实例分割的合并：背景类做语义分割，可数物体做实例分割。' },
  { term: '目标跟踪', full: 'Object Tracking', ch: 4, def: '在连续视频帧中锁定同一目标并维持它的编号，输出位置序列与轨迹。跨帧是它与检测的关键区别。' },
  { term: '边界框', full: 'Bounding Box', ch: 4, def: '框住目标的矩形，通常用左上角坐标与宽高 (x, y, w, h) 表示，是目标检测的标准输出。' },
  { term: '置信度', full: 'Confidence', ch: 4, def: '模型对某个检测结果有多确信，通常是一个 0 到 1 的分数，用来过滤低质量预测。' },
  { term: '交并比', full: 'Intersection over Union', alias: ['IOU'], ch: 4, def: '两个边界框交集面积除以并集面积，用来衡量预测框与真实框的重合程度，也用于跟踪中的数据关联。' },
  { term: '卡尔曼滤波', full: 'Kalman Filter', ch: 4, def: '结合运动预测与观测更新来估计目标状态的算法，在跟踪中用于平滑轨迹、预测下一帧位置。' },
  { term: '匈牙利算法', full: 'Hungarian Algorithm', ch: 4, def: '求解二分图最大权匹配的经典算法，跟踪中用来把当前帧的检测框与已有轨迹一一配对。' },
  { term: '数据关联', full: 'Data Association', ch: 4, def: '跟踪中判断当前帧的检测结果属于哪条已有轨迹的过程，常用交并比、外观特征与运动预测作为依据。' },
  { term: '掩码', full: 'Mask', ch: 4, def: '与图像同尺寸的标注矩阵，用不同取值标出每个像素属于哪个类别或哪个实例。' },
  { term: '零样本推理', full: 'Zero-shot Inference', ch: 4, def: '模型在没有针对某任务训练过的情况下直接完成该任务，例如多模态大模型第一次看到某类题目就能给出步骤。' },
  { term: '共享向量空间', full: 'Shared Embedding Space', ch: 4, def: '把图像、文本等不同模态映射到同一个向量空间，使语义相近的对象距离也近，便于比较与融合。' },
  { term: '惯性测量单元', full: 'Inertial Measurement Unit', alias: ['IMU'], ch: 4, def: '由加速度计与陀螺仪等组成的传感器，测量物体的加速度与角速度，常用于姿态估计与运动跟踪。' },
  { term: '激光雷达', full: 'LiDAR', ch: 4, def: '发射激光并测量反射时间，得到环境中各点的距离与方位，生成高精度三维点云，常用于自动驾驶。' },
  { term: 'CaptionBot', full: 'CaptionBot', ch: 4, def: '微软推出的图像描述服务，尝试自动为图片生成一句说明，是早期视觉语言交互的代表应用。' },
  { term: 'PaLM-E', full: 'PaLM-E', ch: 4, def: '谷歌的多模态具身模型，把视觉、语言与机器人动作结合，能够理解场景并指导机器人完成抓取等任务。' },
  { term: 'LAB', full: 'CIELAB Color Space', ch: 4, def: '设备无关的颜色空间，用亮度与两个色度通道表示颜色，接近人眼感知，适合色彩校正与色差计算。' },
  { term: 'CT', full: 'Computed Tomography', ch: 4, def: '计算机断层扫描，用多个角度的 X 射线投影重建人体内部结构，是医学影像分析的常见数据来源。' },
  { term: 'MRI', full: 'Magnetic Resonance Imaging', ch: 4, def: '磁共振成像，利用磁场与射频信号生成人体软组织的高对比度图像，常用于肿瘤与器官检查。' },
  { term: 'X 光', full: 'X-ray', ch: 4, def: '利用 X 射线穿透人体后成像的检查方式，擅长观察骨骼与肺部，图像是二维投影。' },
  { term: '点云', full: 'Point Cloud', ch: 4, def: '由大量三维坐标点构成的环境表示，通常由激光雷达或深度相机采集，用于三维感知与重建。' },
  { term: '深度图', full: 'Depth Map', ch: 4, def: '每个像素记录到相机距离的图像，用灰度或伪彩色表示远近，是三维重建与避障的重要输入。' },
  { term: 'AR', full: 'Augmented Reality', alias: ['增强现实'], ch: 4, def: '把虚拟内容叠加到真实场景上的技术，需要实时理解环境与相机位置，目标跟踪与语义分割常作为支撑。' },
  { term: 'DALL·E', full: 'DALL·E', alias: ['DALL·E 3'], ch: 4, def: 'OpenAI 的文生图模型，根据文字描述生成图像，代表了多模态生成能力的进展。' },

  /* ---------- 第 5 章 ---------- */
  { term: '文本解析', full: 'Text Parsing', ch: 5, def: '把文本拆分成词、短语、句子等结构单元，并分析它们之间的语法关系。' },
  { term: '分词', full: 'Word Segmentation', ch: 5, def: '把连续文本切分成词序列。中文词与词之间没有空格，分词是中文自然语言处理的基础步骤。' },
  { term: 'jieba', full: 'jieba Chinese Word Segmentation', alias: ['结巴分词'], ch: 5, def: 'Python 生态常用的中文分词库，支持精确模式、全模式、搜索引擎模式，并提供关键词提取与词性标注。' },
  { term: 'NLTK', full: 'Natural Language Toolkit', ch: 5, def: '英文自然语言处理的教学与研究工具包，内置语料、分词、词性标注与句法分析等基础功能。' },
  { term: 'HanLP', full: 'Han Language Processing', ch: 5, def: '中文自然语言处理工具包，提供分词、词性标注、命名实体识别、依存分析等功能。' },
  { term: 'THULAC', full: 'THU Lexical Analyzer for Chinese', ch: 5, def: '清华大学推出的中文词法分析工具，提供分词与词性标注。' },
  { term: 'pkuseg', full: 'PKU Segmentation', ch: 5, def: '北京大学开发的中文分词工具，支持多领域模型与自定义词典。' },
  { term: 'LTP', full: 'Language Technology Platform', ch: 5, def: '哈工大的中文自然语言处理平台，覆盖分词、词性标注、句法分析与语义分析。' },
  { term: 'TensorFlow', full: 'TensorFlow', ch: 5, def: '谷歌开源的深度学习框架，用于搭建与训练神经网络，不直接提供中文分词功能。' },
  { term: 'PyTorch', full: 'PyTorch', ch: 5, def: 'Meta 开源的深度学习框架，以动态计算图与易用接口著称，广泛用于研究与生产。' },
  { term: 'TextRank', full: 'TextRank', ch: 5, def: '基于图排序的关键词与摘要抽取算法，把词或句子当作节点，用共现关系构建图并计算重要性。' },
  { term: '语料库', full: 'Corpus', ch: 5, def: '按一定规则收集与整理的大规模文本集合，是训练语言模型、统计词频与评测系统的基础资源。' },
  { term: 'BIOES', full: 'BIOES Tagging', ch: 5, def: '比 BIO 更细的序列标注格式，增加 E 表示实体结尾、S 表示单字实体，能更清楚地区分实体边界。' },
  { term: '停用词', full: 'Stop Word', ch: 5, def: '在文本分析中没有实际区分意义的常见词，例如「的」「是」「a」。去掉它们可以减少噪声与计算量。' },
  { term: '词干提取', full: 'Stemming', ch: 5, def: '机械截断英文词尾得到词干，例如 studies 变成 studi。结果可能拼不成合法单词。' },
  { term: '词形还原', full: 'Lemmatization', ch: 5, def: '结合词典与词性把词还原成规范原形，例如 better 变成 good。结果一定是合法单词。' },
  { term: '词袋模型', full: 'Bag of Words', alias: ['BoW'], ch: 5, def: '把文档看成词的集合，只统计词表中每个词出现的次数，忽略词序。它实现简单，但会丢失语序与语义相似度。' },
  { term: 'TF-IDF', full: 'Term Frequency-Inverse Document Frequency', ch: 5, def: '词频乘以逆文档频率：词在当前文档出现越多、在全部文档出现越少，权重越高。它用来突出关键词，仍然不保留词序。' },
  { term: 'LDA 主题模型', full: 'Latent Dirichlet Allocation', alias: ['LDA'], ch: 5, def: '无监督主题模型，假设每篇文档由若干主题混合而成、每个主题对应一组词的概率分布，用来发现文档的潜在主题。' },
  { term: 'N-gram', full: 'N-gram', ch: 5, def: '连续 N 个词元组成的片段。它用前 N−1 个词预测下一个词，能保留局部词序，但看不到窗口之外的信息。' },
  { term: '隐马尔可夫模型', full: 'Hidden Markov Model', alias: ['HMM'], ch: 5, def: '用不可观测的状态序列生成可观测序列的概率模型，常用于序列标注与语音识别。' },
  { term: '条件随机场', full: 'Conditional Random Field', alias: ['CRF'], ch: 5, def: '在给定输入序列的条件下建模输出标签序列的判别式模型，能考虑相邻标签之间的约束，常用于命名实体识别。' },
  { term: '词向量', full: 'Word Vector', ch: 5, def: '把词映射成数值向量，使语义相近的词在向量空间中距离也近，计算机才能对文本做数值计算。' },
  { term: '词嵌入', full: 'Word Embedding', alias: ['Embedding'], ch: 5, def: '把词、句子或图像映射成稠密向量的表示方法，语义相近的对象在空间中彼此靠近。' },
  { term: 'Word2Vec', full: 'Word2Vec', ch: 5, def: '2013 年提出的词向量训练方法，用局部上下文学习词的向量表示，包含 CBOW 与 Skip-gram 两种结构。' },
  { term: 'GloVe', full: 'Global Vectors', ch: 5, def: '2014 年提出的词向量方法，结合全局词共现统计与局部上下文，训练出语义关系稳定的词向量。' },
  { term: 'CBOW', full: 'Continuous Bag of Words', ch: 5, def: 'Word2Vec 的一种结构：用周围的上下文词预测中心词。' },
  { term: 'Skip-gram', full: 'Skip-gram', ch: 5, def: 'Word2Vec 的一种结构：用中心词预测周围的上下文词，方向与 CBOW 相反。' },
  { term: '语言模型', full: 'Language Model', ch: 5, def: '计算一个词序列出现概率、或预测下一个词概率的模型，是文本生成、翻译、对话的基础。' },
  { term: '自回归', full: 'Autoregressive', ch: 5, def: '按从左到右的顺序逐个生成词元，每一步都把已生成的内容作为下一步的输入。GPT 采用这种生成方式。' },
  { term: '因果掩码', full: 'Causal Mask', ch: 5, def: '在自注意力中遮住当前位置之后的词元，保证模型只能看到已经生成的内容，防止训练时偷看答案。' },
  { term: '词元', full: 'Token', alias: ['Token', 'Tokens'], ch: 5, def: '模型处理文本的最小单位，可以是一个字、一个词或一个子词片段。上下文长度与计费通常按词元数量计算。' },
  { term: '词表', full: 'Vocabulary', ch: 5, def: '模型认识的全部词元的集合，每个词元对应一个编号，文本先被切分成词元再转成编号序列。' },
  { term: '未知词标记', full: 'Unknown Token', alias: ['UNK'], ch: 5, def: '词表之外的词统一映射成的特殊标记，避免模型遇到没见过的词时无法处理。' },
  { term: '依存关系分析', full: 'Dependency Parsing', ch: 5, def: '分析句子中词与词之间的直接语法依赖，找出核心词以及各词依附于谁。' },
  { term: '短语结构分析', full: 'Constituency Parsing', ch: 5, def: '把句子逐层分解成名词短语、动词短语等嵌套结构，得到一棵句法树。' },
  { term: 'BIO 标注', full: 'BIO Tagging', ch: 5, def: '序列标注格式：B 表示实体开头，I 表示实体内部，O 表示实体外部。它让模型能够标出实体的边界。' },
  { term: 'BiLSTM-CRF', full: 'BiLSTM-CRF', ch: 5, def: '用双向 LSTM 提取上下文特征、再用条件随机场约束标签序列的命名实体识别模型。' },
  { term: '情感分析', full: 'Sentiment Analysis', ch: 5, def: '判断文本的情感倾向与态度极性，例如正面、负面或中性，常用于评论分析与舆情监控。' },
  { term: '意图识别', full: 'Intent Recognition', ch: 5, def: '判断用户一句话想完成什么任务，例如「预订机票」，是对话系统理解用户需求的关键步骤。' },
  { term: '舆情监控', full: 'Public Opinion Monitoring', ch: 5, def: '持续收集与分析网络上的公众讨论，判断情绪倾向与传播趋势，用于危机预警与政策反馈。' },
  { term: '模板生成', full: 'Template-based Generation', ch: 5, def: '预先写好带槽位的句式，再把结构化数据填入槽位。输出可控、格式规范，但灵活性低。' },
  { term: '下一句预测', full: 'Next Sentence Prediction', alias: ['NSP'], ch: 5, def: 'BERT 的预训练任务之一：判断两个句子在原文中是否相邻，用来学习句子之间的关系。' },
  { term: 'BERT', full: 'Bidirectional Encoder Representations from Transformers', ch: 5, def: 'Encoder-only 的双向 Transformer，用掩码语言模型与下一句预测预训练，擅长分类、命名实体识别、问答等理解任务。' },
  { term: 'GPT', full: 'Generative Pre-trained Transformer', ch: 5, def: 'Decoder-only 的单向 Transformer，用自回归方式预测下一个词元，擅长续写、对话、写作等生成任务。' },
  { term: '层归一化', full: 'Layer Normalization', alias: ['LayerNorm'], ch: 5, def: '对单个样本的同一层神经元输出做标准化，稳定训练，不依赖批次大小，适合序列模型。' },
  { term: '低资源语言', full: 'Low-resource Language', ch: 5, def: '可用语料很少的语言。通过跨语言迁移、构建语料库与多语言预训练，可以缓解数据不足。' },
  { term: '跨语言迁移', full: 'Cross-lingual Transfer', ch: 5, def: '把高资源语言上学到的模型能力迁移到低资源语言，减少目标语言的标注需求。' },
  { term: '序列标注', full: 'Sequence Labeling', ch: 5, def: '为序列中的每个词元分配一个标签，例如词性、实体边界。命名实体识别与词性标注都属于这一类。' },
  { term: '掩码', full: 'Mask', ch: 5, def: '把部分词元遮住、让模型只能根据剩余内容预测的标记方式。掩码语言模型用它构造自监督任务。' },

  /* ---------- 第 6 章 ---------- */
  { term: 'AIGC', full: 'Artificial Intelligence Generated Content', alias: ['生成式人工智能', '生成式 AI'], ch: 6, def: '人工智能生成内容，让模型学习大量数据后生成文本、图像、音频、视频等新内容。核心在于产出原本不存在的内容。' },
  { term: '智能体', full: 'Intelligent Agent', alias: ['Agent'], ch: 6, def: '能够自主感知环境、做出决策并执行行动以实现目标的系统。大模型智能体通常由感知、记忆、规划、工具调用与交互等模块组成。' },
  { term: 'PGC', full: 'Professional Generated Content', ch: 6, def: '专业生产内容，由机构、媒体与专业创作者产出，通常有编辑审核与质量标准。' },
  { term: 'UGC', full: 'User Generated Content', ch: 6, def: '用户生产内容，由普通用户在社交平台上创作与分享，数量庞大、质量参差。' },
  { term: '分析式人工智能', full: 'Analytical AI', alias: ['判别式 AI'], ch: 6, def: '做分类、回归、预测的人工智能，输入数据后输出判断或数值，不创造新内容。人脸识别与垃圾邮件拦截属于这一类。' },
  { term: '生成器', full: 'Generator', ch: 6, def: '生成对抗网络中负责从随机噪声生成假样本的网络，目标是骗过判别器。' },
  { term: '判别器', full: 'Discriminator', ch: 6, def: '生成对抗网络中负责判断样本来自真实数据还是生成器的网络，目标是尽量识破假样本。' },
  { term: '对抗训练', full: 'Adversarial Training', ch: 6, def: '让生成器与判别器交替优化、互相博弈的训练方式，双方能力在对抗中共同提升。' },
  { term: '变分自编码器', full: 'Variational Auto-Encoder', alias: ['VAE'], ch: 6, def: '编码器学习潜在变量的概率分布、解码器从中采样重构数据的生成模型。训练稳定、潜在空间连续，生成结果偏模糊。' },
  { term: '自编码器', full: 'Auto-Encoder', ch: 6, def: '由编码器与解码器组成的网络，先把输入压缩成低维表示，再还原输入，目标是让重构误差最小。' },
  { term: '潜在变量', full: 'Latent Variable', ch: 6, def: '数据背后不可直接观测的低维因素，例如人脸的姿态、光照、身份。生成模型通过学习潜在变量来控制生成结果。' },
  { term: '后验分布', full: 'Posterior Distribution', ch: 6, def: '在观测到数据之后，潜在变量的条件概率分布，VAE 的编码器学习的就是 q(z|x)。' },
  { term: '似然', full: 'Likelihood', ch: 6, def: '在给定参数或潜在变量的条件下，观测到当前数据的概率。VAE 的解码器建模 p(x|z)。' },
  { term: 'U-Net', full: 'U-Net', ch: 6, def: '带跳跃连接的编码器解码器卷积网络，最初用于医学图像分割，也是扩散模型去噪网络常用的结构。' },
  { term: '扩散模型', full: 'Diffusion Model', ch: 6, def: '先按预定日程逐步加噪把数据破坏成噪声，再训练网络逐步去噪还原的生成模型，是当前文生图的主流路线。' },
  { term: '正向扩散', full: 'Forward Diffusion', ch: 6, def: '预先设定好的加噪过程，把原始图像逐步变成高斯噪声。它不需要学习，用来制造训练样本。' },
  { term: '逆向扩散', full: 'Reverse Diffusion', ch: 6, def: '从纯噪声出发逐步去噪、恢复出清晰图像的过程，由神经网络学习。' },
  { term: '去噪', full: 'Denoising', ch: 6, def: '从带噪数据中预测并去除噪声，恢复干净内容。扩散模型在每一步都学习预测当前噪声。' },
  { term: '调度器', full: 'Scheduler', ch: 6, def: '控制扩散模型每一步加噪或去噪强度与步数的组件，影响生成质量与速度。' },
  { term: '文生图', full: 'Text-to-Image', ch: 6, def: '输入文字描述、输出对应图像的跨模态生成任务，代表产品有 Midjourney、DALL·E、Stable Diffusion。' },
  { term: '文生视频', full: 'Text-to-Video', ch: 6, def: '输入文字描述、输出一段视频的跨模态生成任务，Sora 是代表产品。' },
  { term: '语音合成', full: 'Text-to-Speech', alias: ['TTS'], ch: 6, def: '把文本转换成自然语音，包括音色克隆与韵律控制。' },
  { term: '语音识别', full: 'Automatic Speech Recognition', alias: ['ASR'], ch: 6, def: '把音频中的语音转换成文字，是语音转文本的核心技术。' },
  { term: '图像描述', full: 'Image Captioning', ch: 6, def: '输入一张图像、生成一句或多句自然语言描述，属于图像到文本的跨模态任务。' },
  { term: '奖励模型', full: 'Reward Model', alias: ['RM'], ch: 6, def: '给模型输出打分、评估其符合人类偏好程度的模型，用于强化学习阶段提供奖励信号。' },
  { term: 'RLHF', full: 'Reinforcement Learning from Human Feedback', alias: ['基于人类反馈的强化学习'], ch: 6, def: '先用人类偏好训练奖励模型，再用强化学习引导大模型生成更符合人类期望的回答。' },
  { term: '提示词', full: 'Prompt', alias: ['Prompt'], ch: 6, def: '用户给模型的输入指令与上下文，用来引导模型生成特定主题、格式或风格的内容。' },
  { term: '提示工程', full: 'Prompt Engineering', ch: 6, def: '设计、组织与优化提示词的方法，包括设定角色、给出示例、约束输出格式、要求分步推理等。' },
  { term: '思维链', full: 'Chain of Thought', alias: ['CoT'], ch: 6, def: '要求模型把推理过程分步写出来再给出结论的方法，能提升复杂推理任务的准确率。' },
  { term: '检索增强生成', full: 'Retrieval-Augmented Generation', alias: ['RAG'], ch: 6, def: '先从外部知识库检索相关片段，再把片段与问题一起交给大模型生成答案，用来缓解知识过时与事实性错误。' },
  { term: '知识库', full: 'Knowledge Base', ch: 6, def: '结构化或非结构化资料的集合，供检索系统查找事实依据，例如产品文档、政策文件、企业资料。' },
  { term: '图数据库', full: 'Graph Database', ch: 6, def: '以节点与边存储实体及其关系的数据库，擅长多跳关系查询，适合知识图谱与检索增强系统。' },
  { term: '幻觉', full: 'Hallucination', ch: 6, def: '模型生成看似流畅可信、实际与事实或给定材料不符的内容，例如编造论文、案例、接口与法条。' },
  { term: '工具调用', full: 'Tool Calling', ch: 6, def: '大模型在需要时调用外部函数、接口或服务完成计算、查询与操作，是智能体执行实际任务的基础。' },
  { term: '链式工作流', full: 'Chained Workflow', ch: 6, def: '多个步骤按线性顺序组织，前一步的输出作为后一步的输入，适合流程固定、前后依赖明确的任务。' },
  { term: '并行化工作流', full: 'Parallel Workflow', ch: 6, def: '同时执行多个子任务或处理多份数据，再汇总结果，适合彼此独立、数据量大的任务。' },
  { term: '路由工作流', full: 'Routing Workflow', ch: 6, def: '根据输入内容动态选择后续执行路径，不需要预先写死完整序列，适合输入类型多样的场景。' },
  { term: 'Ollama', full: 'Ollama', ch: 6, def: '在个人电脑上运行开源大模型的开源工具，提供模型下载、运行与接口调用。' },
  { term: 'AnythingLLM', full: 'AnythingLLM', ch: 6, def: '带图形界面与知识库管理功能的应用框架，可以接入本地模型与向量模型，搭建个人知识问答。' },
  { term: 'BGE-M3', full: 'BGE-M3', ch: 6, def: '把文档转换成向量表示的嵌入模型，用于知识库的语义检索。' },
  { term: '量化', full: 'Quantization', ch: 6, def: '用更低位宽表示模型参数，例如从 16 位降到 4 位，以降低显存占用与运行成本，代价是精度略有下降。' },
  { term: '量化', full: 'Quantization', ch: 4, def: '把事物用数值或离散等级表示。图像位深决定颜色分成多少级；把模型参数从高精度压到低精度也叫量化。' },
  { term: '本地部署', full: 'Local Deployment', ch: 6, def: '把模型与配套软件运行在自己的电脑或服务器上，数据不出本地，适合隐私敏感与离线场景。' },
  { term: '红队测试', full: 'Red Teaming', ch: 6, def: '组织专门人员主动寻找模型的安全漏洞、偏见与有害输出，在发布前暴露风险并修复。' },
  { term: '深度伪造', full: 'Deepfake', alias: ['Deepfake'], ch: 8, def: '用生成模型换脸、拟声或伪造视频，制作以假乱真的人物影像，常被用于诈骗与虚假信息传播。' },
  { term: '数据偏差', full: 'Data Bias', ch: 6, def: '训练数据在某些群体、地域或情境上样本不足或带有历史刻板印象，模型会把这些偏差当成规律学习并放大。' },
  { term: 'CLIP', full: 'Contrastive Language-Image Pre-training', ch: 6, def: '图文对比预训练模型，把图像与文本映射到同一向量空间，文生图中常用它把文字描述编码成条件向量。' },
  { term: 'Stable Diffusion', full: 'Stable Diffusion', ch: 6, def: '开源的潜在扩散文生图模型，在压缩后的潜在空间中做去噪，生成速度快、可本地运行。' },
  { term: 'Midjourney', full: 'Midjourney', ch: 6, def: '以艺术风格见长的文生图服务，用户通过文字描述生成图像。' },
  { term: 'Sora', full: 'Sora', ch: 6, def: 'OpenAI 发布的文生视频模型，能根据文字生成时长较长、场景连贯的视频。' },
  { term: 'ChatGPT', full: 'ChatGPT', ch: 6, def: 'OpenAI 的对话式大语言模型产品，2022 年底发布后把生成式人工智能带入大众视野。' },
  { term: 'DeepSeek-R1', full: 'DeepSeek-R1', ch: 6, def: 'DeepSeek 的推理模型版本，重点提升数学、代码与逻辑推理能力，可本地部署。' },
  { term: 'Llama', full: 'Large Language Model Meta AI', ch: 6, def: 'Meta 发布的开源大语言模型系列，提供多种参数规模，可在个人电脑上量化运行。' },
  { term: 'Qwen', full: 'Qwen', alias: ['通义千问'], ch: 6, def: '阿里巴巴的通义千问大模型系列，覆盖语言、视觉与多模态能力。' },
  { term: 'ChatGLM', full: 'ChatGLM', ch: 6, def: '智谱与清华大学团队的中英双语大模型系列，提供可本地部署的开源版本。' },
  { term: 'Coze', full: 'Coze', alias: ['扣子'], ch: 6, def: '字节跳动的智能体搭建平台，通过提示词、知识库与插件配置机器人，并发布到多种聊天渠道。' },
  { term: '潜空间', full: 'Latent Space', ch: 6, def: '模型压缩后的低维表示空间。扩散模型在潜空间中做去噪，比直接处理像素更省计算。' },

  /* ---------- 第 7 章 ---------- */
  { term: '具身智能', full: 'Embodied Artificial Intelligence', alias: ['EAI'], ch: 7, def: '强调智能来自身体、环境与智能体三者互动的方向。智能体通过传感器感知、通过执行器行动，在真实世界反馈中学习。' },
  { term: '具身小脑', full: 'Embodied Cerebellum', ch: 7, def: '负责运动协调与实时控制的模块，要求毫秒级响应，与负责认知规划的大模型分工协作。' },
  { term: '非自主机器人', full: 'Non-autonomous Robot', ch: 7, def: '由人类控制或按预先编程执行固定动作的机器人，没有独立决策能力，例如流水线机械臂。' },
  { term: '自主机器人', full: 'Autonomous Robot', ch: 7, def: '配备多种传感器与智能算法，能够感知环境、根据目标自主决策并执行动作的机器人。' },
  { term: '外感受传感器', full: 'Exteroceptive Sensor', ch: 7, def: '感知外部环境的传感器，例如摄像头、雷达、红外，用来避障、识别物体与房间边界。' },
  { term: '内感受传感器', full: 'Proprioceptive Sensor', ch: 7, def: '感知机器人自身状态的传感器，例如惯性测量单元、轮式编码器，用来估计速度、姿态与位置。' },
  { term: '惯性传感器', full: 'Inertial Sensor', ch: 7, def: '测量加速度与角速度的传感器，包括加速度计与陀螺仪，用于姿态估计与短时定位。' },
  { term: '编码器', full: 'Encoder', ch: 7, def: '这里指测量电机或车轮转速、转角的传感器，为里程计与闭环控制提供反馈。在神经网络中，编码器指把输入转换成特征表示的模块。' },
  { term: '路径规划', full: 'Path Planning', ch: 7, def: '在环境地图中计算从当前位置到目标位置的安全路线，并在环境变化时重新规划。' },
  { term: 'A* 算法', full: 'A-star Algorithm', alias: ['A*'], ch: 7, def: '结合已走代价与到目标启发式估计的最佳优先搜索算法，能在网格地图上高效找到最短路径。' },
  { term: '最佳优先搜索', full: 'Best-first Search', ch: 7, def: '每次优先扩展看起来最有希望的节点，用启发式函数估计距离目标的远近。' },
  { term: '覆盖策略', full: 'Coverage Strategy', ch: 7, def: '扫地机器人安排清扫顺序的规则，例如弓字形来回行走配合延边清扫，追求覆盖全面与路径较短。' },
  { term: '差速转向', full: 'Differential Steering', ch: 7, def: '通过左右轮速度差实现转向，左轮加速、右轮减速时车体向右转。' },
  { term: '语义地图', full: 'Semantic Map', ch: 7, def: '在几何地图上为物体与区域标注语义标签，例如厨房、沙发、充电桩，让机器人理解自然语言目标。' },
  { term: '双目视觉', full: 'Stereo Vision', ch: 7, def: '用两个摄像头从不同视角拍摄同一场景，根据视差计算深度。硬件简单、成本低，但受光照影响较大。' },
  { term: '飞行时间', full: 'Time of Flight', alias: ['TOF'], ch: 7, def: '通过测量光或声波往返时间计算距离的方法，实时性好、计算简单，像素密度通常较低。' },
  { term: '结构光', full: 'Structured Light', ch: 7, def: '向场景投射已知图案，根据图案形变计算深度。近距离精度高、弱光稳定，强光下受干扰且硬件较贵。' },
  { term: '大语言模型', full: 'Large Language Model', alias: ['LLM'], ch: 7, def: '在海量文本上预训练、以文本为输入与输出的模型，具备理解、推理与生成语言的能力。' },
  { term: '视觉语言模型', full: 'Vision-Language Model', alias: ['VLM'], ch: 7, def: '同时接受图像与文本输入、输出文本的模型，能完成看图说话、视觉问答等跨模态理解任务。' },
  { term: '视觉语言动作模型', full: 'Vision-Language-Action Model', alias: ['VLA'], ch: 7, def: '在视觉语言模型基础上增加动作输出，把感知与语言指令直接转成机器人控制动作，用于具身操作。' },
  { term: '视觉语言导航', full: 'Vision-Language Navigation', alias: ['VLN'], ch: 7, def: '机器人根据自然语言指令与视觉信息在环境中导航到目标位置，核心是找路并完成指令。' },
  { term: 'RT-2', full: 'Robotics Transformer 2', ch: 7, def: '谷歌的视觉语言动作模型，把视觉语言预训练知识迁移到机器人控制，提高了新任务上的泛化能力。' },
  { term: '指令导向导航', full: 'Instruction-guided Navigation', ch: 7, def: '用户给出具体路径步骤，例如「先直走 5 米再左转」，机器人按步骤执行。' },
  { term: '目标导向导航', full: 'Goal-guided Navigation', ch: 7, def: '用户只给出最终目的地，例如「去厨房」，路径由系统自行规划。' },
  { term: '需求导向导航', full: 'Need-guided Navigation', ch: 7, def: '用户表达状态或愿望，例如「我困了」，机器人推断潜在需求并自行决定去哪里。' },
  { term: '对话导向导航', full: 'Dialogue-guided Navigation', ch: 7, def: '通过多轮对话逐步明确用户需求并调整路线，依赖人机交互消除歧义。' },
  { term: '触觉', full: 'Tactile Sensing', ch: 7, def: '机器人通过接触感知压力、力矩、滑动、温度等信息，用来判断抓取是否稳固、力度是否合适。' },
  { term: '电子皮肤', full: 'Electronic Skin', ch: 7, def: '由柔性材料与传感器阵列构成的覆盖层，可贴合曲面，模拟人类皮肤的分布式触觉感知。' },
  { term: '压觉', full: 'Pressure Sensing', ch: 7, def: '感知接触面压力大小与分布的触觉能力，用于控制夹持力度。' },
  { term: '滑觉', full: 'Slip Detection', ch: 7, def: '感知物体在手指间滑动趋势的触觉能力，机器人据此及时加大夹持力。' },
  { term: '力矩觉', full: 'Force-Torque Sensing', ch: 7, def: '感知接触力与旋转力矩的触觉能力，用于精密装配与柔顺控制。' },
  { term: '马尔可夫决策过程', full: 'Markov Decision Process', alias: ['MDP'], ch: 7, def: '描述强化学习问题的数学框架，由状态、动作、状态转移概率与奖励构成，下一状态只依赖当前状态与动作。' },
  { term: 'Q-learning', full: 'Q-learning', ch: 7, def: '一种无模型的强化学习算法，学习每个状态动作对的长期回报估计，再按估计选择动作。' },
  { term: '状态转移', full: 'State Transition', ch: 7, def: '执行动作后从当前状态进入下一个状态的过程，可能带有随机性。' },
  { term: '轨迹', full: 'Trajectory', ch: 7, def: '智能体在环境中经历的状态与动作序列；在目标跟踪中则指目标随时间的位置序列。' },
  { term: '累积奖励', full: 'Cumulative Reward', ch: 7, def: '一条轨迹上所有奖励的总和，强化学习优化的目标是让它尽可能大，单步奖励不构成评价标准。' },
  { term: '仿真', full: 'Simulation', ch: 7, def: '在计算机中构建物理世界的高保真虚拟环境，可以并行运行大量试验、零硬件损耗，用于训练机器人策略。' },
  { term: 'sim-to-real', full: 'Simulation to Reality', alias: ['仿真到现实的迁移'], ch: 7, def: '把仿真环境中训练好的策略部署到真实机器人。真实世界的摩擦、光照与传感器噪声与仿真不同，通常需要继续微调。' },
  { term: '世界模型', full: 'World Model', ch: 7, def: '让智能体在行动之前于内部推演环境变化与行动后果的模型，支持反事实推理与风险预判。' },
  { term: '反事实推理', full: 'Counterfactual Reasoning', ch: 7, def: '推演「如果采取另一种做法会发生什么」，比较多种可能未来，帮助智能体选择更好的行动。' },
  { term: 'Genie 2', full: 'Genie 2', ch: 7, def: '谷歌的世界模型，能从单张图片生成可交互的三维场景，为具身智能提供大量虚拟训练环境。' },
  { term: '人形机器人', full: 'Humanoid Robot', ch: 7, def: '模仿人类形态与运动方式的机器人，能够适应为人类设计的家庭与公共环境，被视为具身智能的终极形态。' },
  { term: '自动驾驶', full: 'Autonomous Driving', ch: 7, def: '车辆依靠传感器、感知算法与规划控制自主行驶。端到端方案直接从传感器输入生成轨迹与控制指令。' },
  { term: 'MindVLA', full: 'MindVLA', ch: 7, def: '理想汽车发布的视觉语言动作模型，用于自动驾驶，直接根据感知与语言信息输出驾驶决策。' },
  { term: '达芬奇手术机器人', full: 'da Vinci Surgical System', ch: 7, def: '由医生主控台、床旁机械臂手术平台与成像系统组成的微创手术机器人，能完成精细剥离与缝合。' },
  { term: '因果推断', full: 'Causal Inference', ch: 7, def: '从观测数据中区分相关与因果、估计干预效果的方法，用于消除算法决策中的歧视性关联。' },

  /* ---------- 第 8 章 ---------- */
  { term: '数字鸿沟', full: 'Digital Divide', ch: 8, def: '不同群体在数字技术接入、使用能力与收益上的差距，已经从设备接入差异扩展到素养与智能技术使用差异。' },
  { term: '数据隐私', full: 'Data Privacy', ch: 8, def: '个人对自身数据的收集、存储、使用与传播的控制权，以及数据不被滥用的权利。' },
  { term: '数据主权', full: 'Data Sovereignty', ch: 8, def: '国家或组织对其境内数据拥有管理与控制权的主张，涉及数据跨境流动与本地存储要求。' },
  { term: '剑桥分析', full: 'Cambridge Analytica', ch: 8, def: '2018 年曝光的政治咨询公司数据丑闻，通过性格测试应用收集数千万 Facebook 用户及其好友的数据，用于精准政治广告投放。' },
  { term: '美国联邦贸易委员会', full: 'Federal Trade Commission', alias: ['FTC'], ch: 8, def: '美国负责消费者保护与反垄断的联邦机构，2020 年与 Facebook 就隐私问题达成 50 亿美元和解。' },
  { term: 'GDPR', full: 'General Data Protection Regulation', alias: ['通用数据保护条例'], ch: 8, def: '欧盟通用数据保护条例，规定个人数据的收集、处理、跨境传输与用户权利，是全球隐私立法的重要参照。' },
  { term: 'CCPA', full: 'California Consumer Privacy Act', alias: ['加州消费者隐私法案'], ch: 8, def: '美国加利福尼亚州的消费者隐私法案，赋予居民知情、删除与拒绝出售个人信息的权利。' },
  { term: '勒索软件', full: 'Ransomware', ch: 8, def: '加密或窃取数据、以此要挟受害者支付赎金的恶意软件，近年目标转向政府、能源、医疗等关键领域。' },
  { term: '差分隐私', full: 'Differential Privacy', ch: 8, def: '在查询结果中加入受控噪声，使攻击者无法判断某条个人记录是否在数据集中，从而在统计分析时保护个体隐私。' },
  { term: '隐私计算', full: 'Privacy-preserving Computation', ch: 8, def: '在不暴露原始数据的前提下完成联合计算的技术集合，包括安全多方计算、联邦学习与可信执行环境。' },
  { term: '数据分级分类', full: 'Data Classification', ch: 8, def: '按敏感程度与业务重要性给数据划分等级，对不同等级采取不同的访问控制与保护措施。' },
  { term: '算法偏见', full: 'Algorithmic Bias', ch: 8, def: '算法系统因数据集、特征选择或设计缺陷，对特定群体产生系统性不公平结果的现象，会形成循环反馈并自我强化。' },
  { term: '代理变量', full: 'Proxy Variable', ch: 8, def: '用来替代敏感属性的间接特征，例如用邮编代替种族、用兴趣社团代替性别。模型仍可能借它产生歧视。' },
  { term: 'COMPAS', full: 'Correctional Offender Management Profiling for Alternative Sanctions', ch: 8, def: '用于预测被告再犯风险的司法辅助系统。黑人与白人被误判为高风险的比例存在明显差异，是算法偏见的经典案例。' },
  { term: '再犯风险', full: 'Recidivism Risk', ch: 8, def: '被告未来再次犯罪的可能性估计，COMPAS 用它辅助法官决定量刑、保释或假释。' },
  { term: '系统性不公平', full: 'Systemic Unfairness', ch: 8, def: '某一群体整体上持续承受更差结果的现象，通常源于数据与制度的历史偏差。个别样本的偶然错误不会形成这种格局。' },
  { term: '可解释人工智能', full: 'Explainable Artificial Intelligence', alias: ['XAI'], ch: 8, def: '让模型的决策依据能够被人类理解、审计与问责的技术方向，目标包括可理解、可审计、可问责与可信任。' },
  { term: '黑箱模型', full: 'Black-box Model', ch: 8, def: '内部决策逻辑不透明、难以追溯的模型，例如大型深度神经网络。输入与输出可见，中间推理过程难以解释。' },
  { term: '决策透明', full: 'Decision Transparency', ch: 8, def: '能够像查账一样一步步追溯模型的决策过程，强调过程可复现，主要面向审计与追责。' },
  { term: '可解释性', full: 'Interpretability', ch: 8, def: '能够用普通人可以理解的方式说明模型为何给出某个结论，强调结论可懂，主要面向使用者。' },
  { term: '事后解释', full: 'Post-hoc Explanation', ch: 8, def: '模型训练完成后，用外部工具或算法解释它的决策依据，适用于已经存在且无法重新设计的黑箱模型。' },
  { term: 'Grad-CAM', full: 'Gradient-weighted Class Activation Mapping', ch: 8, def: '利用梯度生成激活热力图的可视化解释方法，高亮图像中影响模型决策的区域。' },
  { term: '激活热力图', full: 'Activation Heatmap', ch: 8, def: '用颜色深浅表示模型在图像各位置的关注强度，帮助人直观看到模型依据哪些区域做判断。' },
  { term: '可审计', full: 'Auditable', ch: 8, def: '外部人员能够检查模型的决策过程与依据，发现偏见、错误与违规行为。' },
  { term: '可问责', full: 'Accountable', ch: 8, def: '出现问题后能够定位责任主体并追究责任，是高风险场景采用人工智能的前提。' },
  { term: '人类主体性', full: 'Human Subjectivity', ch: 8, def: '人作为主体所具有的能动性、自主性、自我选择与自我决定能力。技术便利可能削弱这种能力。' },
  { term: '信息茧房', full: 'Information Cocoon', ch: 8, def: '桑斯坦提出的概念：推荐算法持续投喂用户偏好的内容，使人接触的信息越来越单一，认知被封闭在蚕茧一样的圈子里。' },
  { term: '桑斯坦', full: 'Cass Sunstein', ch: 8, def: '哈佛大学法学家，2006 年在《信息乌托邦》中提出信息茧房概念，讨论个性化信息环境对公共讨论的影响。' },
  { term: '康德', full: 'Immanuel Kant', ch: 8, def: '德国哲学家，提出人作为主体具有能动性、自主性与自我决定能力，是讨论人类主体性的思想来源。' },
  { term: '过滤气泡', full: 'Filter Bubble', ch: 8, def: '个性化推荐根据用户画像过滤信息，形成每个人看到的世界不同的现象，与信息茧房相互关联。' },
  { term: '用户画像', full: 'User Profile', ch: 8, def: '平台根据行为数据为用户建立的标签集合，用于个性化推荐与广告投放，可能包含数千个特征维度。' },
  { term: '技术依赖', full: 'Technology Dependence', ch: 8, def: '过度依赖技术工具完成原本需要自身能力的事情，导致相关能力退化，例如长期依赖导航削弱空间记忆。' },
  { term: '海马体', full: 'Hippocampus', ch: 8, def: '大脑中与空间记忆、导航密切相关的区域。伦敦出租车司机的后海马体体积更大，长期依赖 GPS 的人则出现萎缩。' },
  { term: '责任归属', full: 'Liability Attribution', ch: 8, def: '在事故或损害发生后，判断应由开发者、使用者还是机构承担责任的过程。人工智能不具备法律人格，责任最终要回溯到人。' },
  { term: '法律人格', full: 'Legal Personhood', ch: 8, def: '法律上能够独立享有权利、承担义务的资格。当前人工智能系统不具备法律人格。' },
  { term: '替代责任', full: 'Vicarious Liability', ch: 8, def: '雇主或机构对其员工、设备在职务范围内造成的损害承担责任。医院可能因医生使用人工智能的诊疗行为承担机构责任。' },
  { term: 'SAE 分级', full: 'SAE Autonomy Levels', alias: ['SAE'], ch: 8, def: '国际汽车工程师协会制定的自动驾驶分级体系，从 L0 无自动化到 L5 完全自动化，L3 是责任划分的关键分界。' },
  { term: 'L2 辅助驾驶', full: 'Level 2 Driver Assistance', alias: ['L2'], ch: 8, def: '车辆能同时控制方向与速度，但驾驶员仍需持续监控环境并随时接管，主流量产车型处于这一级。' },
  { term: 'EDR', full: 'Event Data Recorder', alias: ['事件记录器'], ch: 8, def: '记录事故前后车辆速度、制动、转向等运行数据的设备，用于事故责任判定。' },
  { term: 'DMS', full: 'Driver Monitoring System', alias: ['驾驶员状态监测'], ch: 8, def: '通过摄像头与传感器监测驾驶员是否分心、疲劳或脱离方向盘，并在必要时报警或退出辅助驾驶。' },
  { term: '数字孪生', full: 'Digital Twin', ch: 8, def: '为真实设备或场景建立同步的虚拟模型，用于仿真、监测与事故复现。' },
  { term: '欧盟人工智能法案', full: 'EU Artificial Intelligence Act', ch: 8, def: '2024 年 8 月生效的全球首部全面监管人工智能的法规，按风险等级设定义务，并对生成式人工智能提出透明度要求。' },
  { term: '生成式人工智能服务管理暂行办法', full: 'Interim Measures for the Management of Generative AI Services', ch: 8, def: '中国国家网信办等七部门发布、2023 年 8 月 15 日实施的管理规定，规范训练数据来源、生成内容标记与服务提供者行为。' },
  { term: '情感计算', full: 'Affective Computing', ch: 8, def: '1995 年 Picard 提出的方向：让计算机识别、理解、表达、响应乃至适度模拟人类情感，提升人机交互的自然性。' },
  { term: 'Picard', full: 'Rosalind Picard', ch: 8, def: '麻省理工学院教授，1995 年提出情感计算，主张机器应当能够感知与响应人类情感。' },
  { term: '明斯基', full: 'Marvin Minsky', ch: 8, def: '人工智能奠基者之一，达特茅斯会议参与者，著有《情感机器》，讨论智能与情感的关系。' },
  { term: '情感识别', full: 'Emotion Recognition', ch: 8, def: '从人的表情、语音、文本或生理信号中读取情绪状态。机器在旁边观察与判断，不涉及机器自身产生情感。' },
  { term: '情感模拟', full: 'Emotion Simulation', ch: 8, def: '机器表现出某种情绪，例如虚拟人微笑、语音助手用温柔语气回应。它属于表演层面的生成。' },
  { term: '情感操纵', full: 'Emotional Manipulation', ch: 8, def: '利用情感识别结果影响、诱导用户做出有利于平台的选择，通常带有负面伦理含义。' },
  { term: '情感词典', full: 'Sentiment Lexicon', ch: 8, def: '预先整理的情感词及其极性分值表，配合程度词与否定词规则判断文本情绪。' },
  { term: '程度词', full: 'Intensity Word', ch: 8, def: '用来加强或减弱情感强度的词，例如「极其」「稍微」。它会调整情感词的权重。' },
  { term: '否定词', full: 'Negation Word', ch: 8, def: '用来反转情感极性的词，例如「不」「没有」。「不好看」会由正面翻转为负面。' },
  { term: '语音情感识别', full: 'Speech Emotion Recognition', alias: ['SER'], ch: 8, def: '从语音信号中识别说话人的情绪，通常融合原始音频、MFCC 与梅尔谱等多种特征。' },
  { term: 'MFCC', full: 'Mel-Frequency Cepstral Coefficients', alias: ['梅尔频率倒谱系数'], ch: 8, def: '按人耳对频率的非线性感知提取的语音特征，广泛用于语音识别与语音情感识别。' },
  { term: '梅尔谱', full: 'Mel Spectrogram', ch: 8, def: '把音频转换为梅尔刻度上的时频谱图，既保留时间与频率信息，又贴近人耳感知。' },
  { term: 'BiLSTM', full: 'Bidirectional Long Short-Term Memory', ch: 8, def: '双向长短期记忆网络，同时从前向与后向读取序列，再把两边状态拼接，用于语音与文本特征编码。' },
  { term: 'ICASSP', full: 'International Conference on Acoustics, Speech and Signal Processing', ch: 8, def: '语音、声学与信号处理领域的国际会议，课件引用的语音情感识别工作发表于此。' },
  { term: 'IEMOCAP', full: 'Interactive Emotional Dyadic Motion Capture', ch: 8, def: '多模态情感数据集，包含对话中的音频、视频与文本，常用于训练与评测语音情感识别模型。' },
  { term: 'wav2vec2', full: 'wav2vec 2.0', ch: 8, def: '直接以原始音频为输入的自监督语音预训练模型，能学出通用的语音表示。' },
  { term: 'co-attention', full: 'Co-attention', ch: 8, def: '让多个模态的特征相互计算注意力、彼此融合的机制，用于语音情感识别中的多路特征整合。' },
  { term: '动作单元', full: 'Action Unit', alias: ['AU'], ch: 8, def: '面部动作编码系统中的基本肌肉动作，例如皱眉 AU4、闭眼 AU43。疼痛表情识别会用它们组合描述。' },
  { term: 'Ekman', full: 'Paul Ekman', ch: 8, def: '心理学家，提出六种跨文化的基础表情：快乐、悲伤、愤怒、恐惧、惊讶、厌恶，是人脸情感识别的重要基础。' },
  { term: '太空歌剧院', full: 'Théâtre D’opéra Spatial', ch: 8, def: 'Midjourney 生成的绘画作品，2022 年获美国科罗拉多州博览会美术比赛冠军，引发人工智能作品版权与艺术伦理争议。' },
  { term: 'AI 孙燕姿', full: 'AI Sun Yanzi', alias: ['孙燕姿'], ch: 8, def: '用语音克隆模型模仿歌手孙燕姿音色翻唱歌曲的网络现象，引发关于声音权与人工智能侵权的讨论。' },
  { term: '知情同意', full: 'Informed Consent', ch: 8, def: '收集与使用个人数据前，必须充分告知目的、范围与风险，让当事人理解后自愿同意。情感数据采集尤其需要遵守。' },
  { term: '长尾风险', full: 'Long-tail Risk', ch: 8, def: '发生概率低但后果可能很严重、且种类繁多难以逐一列举的风险。治理上需要持续监测与动态调整。' },
  { term: '敏捷治理', full: 'Agile Governance', ch: 8, def: '快速识别新问题与风险、在较短时间内做出响应并调整规则的治理方式，强调速度。' },
  { term: '适应性治理', full: 'Adaptive Governance', ch: 8, def: '通过长期监测体系持续观察技术与社会变化，不断修正治理框架的治理方式，强调持久。' },
  { term: '技术普惠', full: 'Inclusive Technology', ch: 8, def: '让不同地区、不同群体都能获得并使用人工智能技术，缩小智能鸿沟。' },
  { term: '智能鸿沟', full: 'AI Divide', ch: 8, def: '不同国家、群体在人工智能技术能力与收益上的差距，是数字鸿沟在智能时代的延伸。' }
];
